/**
 * Cash Abstract Report — payment received/paid split.
 *
 * Splits payment rows into received vs. paid buckets per mode. Pure function,
 * used only by set_cashabstract_table() below.
 *
 * Background (RET-CASHABSTRACT-REFUND):
 * The report's `[ R - P ]` rows (CASH, RTGS, IMPS, NEFT) always showed 0.00 on the
 * "Paid" side, even when a billing refund was issued to the customer, because the
 * bill-side payment rows were summed as a single signed net instead of being split
 * into received vs. paid.
 *
 * Source data conventions (verified against ret_billing_payment / ret_issue_rcpt_payment):
 *   - payment_details (ret_billing_payment rows):
 *       item.type == 1  -> money received (payment_amount is positive)
 *       item.type == 2  -> money paid out / refunded (payment_amount is NEGATIVE)
 *     A handful of legacy type==1 rows carry a negative payment_amount too (e.g. a
 *     purchase adjustment) — those are received-side rows and must stay on the
 *     received bucket instead of being reinterpreted as a refund.
 *   - general_pay_details (ret_issue_rcpt_payment rows, aliased transcation_type):
 *       item.transcation_type == 1 -> receipt (payment_amount is positive)
 *       item.transcation_type == 2 -> issue/payout (payment_amount is ALSO positive)
 *
 * Because the sign convention differs between the two sources, the two accumulation
 * helpers below (addBillAmount / addGeneralAmount) deliberately do NOT share code:
 * a type==2 bill row is negated to make `paid` positive; a transcation_type==2
 * general row is added as-is because it is already positive.
 *
 * Guarantee: for every mode, `received - paid` is numerically identical to the
 * legacy single signed accumulator this replaces. That identity is what keeps
 * the report's collection TOTAL from changing.
 */
var CASH_ABSTRACT_PAYMENT_MODES = ['cash', 'card', 'cheque', 'online', 'rtgs', 'imps', 'neft', 'upi'];

function buildCashAbstractPaymentSplit(payment_details, general_pay_details) {
	function emptyBucket() {
		return { received: 0, paid: 0 };
	}

	var bill = {};
	var general = {};
	CASH_ABSTRACT_PAYMENT_MODES.forEach(function (mode) {
		bill[mode] = emptyBucket();
		general[mode] = emptyBucket();
	});

	// ret_billing_payment: type==2 rows carry a negative payment_amount -> negate onto `paid`.
	function addBillAmount(bucket, payment_amount, type) {
		var amt = parseFloat(payment_amount);
		if (isNaN(amt)) {
			return;
		}
		if (type == 2) {
			bucket.paid += -amt;
		} else {
			bucket.received += amt;
		}
	}

	// ret_issue_rcpt_payment: both receipt (1) and issue (2) rows carry a positive amount.
	function addGeneralAmount(bucket, payment_amount, transcation_type) {
		var amt = parseFloat(payment_amount);
		if (isNaN(amt)) {
			return;
		}
		if (transcation_type == 2) {
			bucket.paid += amt;
		} else {
			bucket.received += amt;
		}
	}

	(payment_details || []).forEach(function (item) {
		var mode = item.payment_mode;
		var amount = item.payment_amount;
		var type = item.type;
		var nbType = item.nb_type;

		if (amount == null) {
			return;
		}
		if (mode == 'Cash') {
			addBillAmount(bill.cash, amount, type);
		}
		if (mode == 'CC' || mode == 'DC') {
			addBillAmount(bill.card, amount, type);
		}
		if (mode == 'CHQ') {
			addBillAmount(bill.cheque, amount, type);
		}
		if (mode == 'NB') {
			addBillAmount(bill.online, amount, type);
		}
		if (nbType != null && nbType > 0) {
			if (nbType == 1) {
				addBillAmount(bill.rtgs, amount, type);
			}
			if (nbType == 2) {
				addBillAmount(bill.imps, amount, type);
			}
			if (nbType == 3) {
				addBillAmount(bill.upi, amount, type);
			}
			if (nbType == 4) {
				addBillAmount(bill.neft, amount, type);
			}
		}
	});

	(general_pay_details || []).forEach(function (item) {
		var mode = item.payment_mode;
		var amount = item.payment_amount;
		var txType = item.transcation_type;
		var nbType = item.nb_type;

		if (amount == null) {
			return;
		}
		if (mode == 'Cash') {
			addGeneralAmount(general.cash, amount, txType);
		}
		if (mode == 'CC' || mode == 'DC') {
			addGeneralAmount(general.card, amount, txType);
		}
		if (mode == 'CHQ') {
			addGeneralAmount(general.cheque, amount, txType);
		}
		if (mode == 'NB') {
			addGeneralAmount(general.online, amount, txType);
			if (nbType != null && nbType != 0) {
				if (nbType == 1) {
					addGeneralAmount(general.rtgs, amount, txType);
				}
				if (nbType == 2) {
					addGeneralAmount(general.imps, amount, txType);
				}
				if (nbType == 3) {
					addGeneralAmount(general.upi, amount, txType);
				}
				if (nbType == 4) {
					addGeneralAmount(general.neft, amount, txType);
				}
			}
		}
	});

	return { bill: bill, general: general };
}

