//credit history
function get_ActiveCustomer() {
	$('.overlay').css('display', 'block');
	$.ajax({
		type: 'GET',
		url: base_url + 'index.php/admin_ret_reports/get_bill_customer',
		dataType: 'json',
		success: function (data) {
			var id_village = '';
			$.each(data, function (key, data) {
				$('#select_customer').append(
					$("<option></option>")
						.attr("value", data.id_customer)
						.text(data.mobile + '-' + data.cus_name)
				);
				$('#select_customer').select2({
					placeholder: "Select Customer",
					allowClear: true
				});
				$("#select_customer").select2("val", (id_village != null ? id_village : ''));
			});
			$('.overlay').css('display', 'none');
		},
		error: function (error) {
			$("div.overlay").css("display", "none");
		}
	});
}
function set_credit_history_table() {
	var dt_range = ($("#dt_range").val()).split('-');
	var company_name = $('#company_name').val();
	var from_date = dt_range[0];
	var to_date = dt_range[1];
	var branch_name = ($('#branch_name').val() != '' && $('#branch_name').val() != undefined ? $('#branch_name').val() : $("#branch_select option:selected").text());
	var report_name = "CREDIT SALES HISTORY REPORT";
	var select_customer = $('#select_customer option:selected').html() != '' && $('#select_customer option:selected').html() != undefined ? $('#select_customer option:selected').html() + ' - ' : '';
	var optional = select_customer;
	var title = "<div style='text-align: center;'><b><span style='font-size:15pt;'>" + company_name + "</span></b><b><span style='font-size:12pt;'></span></b></br>"
		+ "<span>" + report_print(branch_name, report_name, from_date, to_date, optional) + "</span>";
	var report_type = 'CREDIT HISTORY REPORT';
	my_Date = new Date();
	$(".overlay").css("display", "block");
	$.ajax({
		url: base_url + "index.php/admin_ret_reports/credit_history/ajax?nocache=" + my_Date.getUTCSeconds(),
		data: ({ 'id_customer': $('#select_customer').val(), 'dt_range': $("#dt_range").val(), 'id_branch': ($('#branch_filter').val() != '' && $('#branch_filter').val() != undefined ? $('#branch_filter').val() : $("#branch_select").val()) }),
		dataType: "JSON",
		type: "POST",
		success: function (data) {
			var list = data.list;
			$("#credit_issued_list > tbody > tr").remove();
			$('#credit_issued_list').dataTable().fnClearTable();
			$('#credit_issued_list').dataTable().fnDestroy();
			if (list != null && list != '') {
				trHTML = '';
				tfootHTML = '';
				total_bill_amount = 0;
				total_paid_amount = 0;
				total_bal_amount = 0;
				total_credit_disc_amt = 0;
				total_credit_ret_amt = 0;
				total_old_metal_amount = 0;
				$.each(list, function (i, branch) {
					var bill_amount = 0;
					var paid_amount = 0;
					var credit_ret_amt = 0;
					var bal_amount = 0;
					var bill_bal_amt = 0;
					var sub_total_bal_amt = 0;
					var credit_disc_amt = 0;
					var old_metal_amount = 0;
					$.each(branch, function (idx, item) {
						if (item.type == 0) {
							var url = base_url + 'index.php/admin_ret_billing/billing_invoice/' + item.bill_id;
						} else {
							var url = base_url + 'index.php/admin_ret_billing/issue/issue_print/' + item.bill_id;
						}
						trHTML += '<tr>' +
							'<td>' + item.branch_name + '</td>'
							+ '<td>' + item.cus_name + '</td>'
							+ '<td>' + item.mobile + '</td>'
							+ '<td><a href=' + url + ' target="_blank">' + item.bill_no + '</a></td>'
							+ '<td>' + item.bill_date + '</td>'
							+ '<td>' + money_format_india(parseFloat(item.tot_bill_amount || 0).toFixed(2)) + '</td>'
							+ '<td>' + money_format_india(parseFloat(item.tot_amt_received || 0).toFixed(2)) + '</td>'
							+ '<td>' + money_format_india(parseFloat(item.credit_disc_amt || 0).toFixed(2)) + '</td>'
							+ '<td>' + money_format_india(parseFloat(item.credit_ret_amt || 0).toFixed(2)) + '</td>'
							+ '<td></td>'
							+ '<td>' + (item.bal_amt > 0 ? money_format_india(parseFloat(item.bal_amt || 0).toFixed(2)) : parseFloat(0).toFixed(2)) + '</td>'
							+ '<td>' + (item.remark ? item.remark : '-') + '</td>'
						'<td></td>' +
						+ '</tr>';
						bill_amount = parseFloat(bill_amount) + parseFloat(item.tot_bill_amount || 0);
						paid_amount = parseFloat(paid_amount) + parseFloat(item.tot_amt_received || 0);
						credit_ret_amt = parseFloat(credit_ret_amt) + parseFloat(item.credit_ret_amt || 0);
						bill_bal_amt = parseFloat(item.bal_amt || 0);
						sub_total_bal_amt += parseFloat(item.bal_amt || 0);
						if ((item.credit_collection).length > 0) {
							$.each(item.credit_collection, function (key, value) {
								var url = base_url + 'index.php/admin_ret_billing/billing_invoice/' + value.bill_id;
								bill_bal_amt = parseFloat(bill_bal_amt) - parseFloat(value.tot_amt_received || 0) - parseFloat(value.credit_disc_amt || 0) - parseFloat(value.old_metal_amount || 0);
								credit_disc_amt += parseFloat(value.credit_disc_amt || 0);
								old_metal_amount += parseFloat(value.old_metal_amount || 0);
								if (item.type == 0) {
									var url = base_url + 'index.php/admin_ret_billing/billing_invoice/' + value.bill_id;
								} else {
									var url = base_url + 'index.php/admin_ret_billing/receipt/receipt_print/' + value.bill_id;
								}
								trHTML += '<tr>' +
									'<td></td>'
									+ '<td></td>'
									+ '<td></td>'
									+ '<td><a href=' + url + ' target="_blank">' + value.bill_no + '</a></td>'
									+ '<td>' + value.bill_date + '</td>'
									+ '<td>' + (parseFloat(value.tot_bill_amount || 0) + parseFloat(value.credit_disc_amt || 0)).toFixed(2) + '</td>'
									+ '<td>' + money_format_india(parseFloat(value.tot_amt_received || 0).toFixed(2)) + '</td>'
									+ '<td>' + money_format_india(parseFloat(value.credit_disc_amt || 0).toFixed(2)) + '</td>'
									+ '<td></td>'
									+ '<td>' + money_format_india(parseFloat(value.old_metal_amount || 0).toFixed(2)) + '</td>'
									+ '<td>' + money_format_india(Math.max(0, parseFloat(bill_bal_amt)).toFixed(2)) + '</td>'
									+ '<td>' + (value.remark ? value.remark : '-') + '</td>'
								'<td></td>' +
								+ '</tr>';
								paid_amount = parseFloat(paid_amount) + parseFloat(value.tot_amt_received || 0);
								sub_total_bal_amt -= parseFloat(parseFloat(value.tot_amt_received || 0) + parseFloat(value.old_metal_amount || 0) + parseFloat(value.credit_disc_amt || 0))
							});
						}
					});
					trHTML += '<tr style="font-weight:bold;color:red">' +
						'<td></td>'
						+ '<td></td>'
						+ '<td></td>'
						+ '<td></td>'
						+ '<td>Sub Total</td>'
						+ '<td>' + money_format_india(bill_amount || 0) + '</td>'
						+ '<td>' + money_format_india(paid_amount || 0) + '</td>'
						+ '<td>' + money_format_india(credit_disc_amt || 0) + '</td>'
						+ '<td></td>'
						+ '<td>' + money_format_india(old_metal_amount || 0) + '</td>'
						+ '<td>' + money_format_india(Math.max(0, parseFloat(sub_total_bal_amt || 0)).toFixed(2)) + '</td>'
						+ '<td></td>'
					'<td></td>' +
					+ '</tr>';
					total_bill_amount = total_bill_amount + bill_amount;
					total_paid_amount = total_paid_amount + paid_amount;
					total_bal_amount = total_bal_amount + (sub_total_bal_amt);
					total_credit_disc_amt = total_credit_disc_amt + credit_disc_amt;
					total_credit_ret_amt = total_credit_ret_amt + credit_ret_amt;
					total_old_metal_amount = total_old_metal_amount + old_metal_amount;
				});
				trHTML += '<tr style="font-weight:bold;color:blue">' +
					'<td></td>'
					+ '<td></td>'
					+ '<td></td>'
					+ '<td></td>'
					+ '<td>Grand Total</td>'
					+ '<td>' + money_format_india(total_bill_amount || 0) + '</td>'
					+ '<td>' + money_format_india(total_paid_amount || 0) + '</td>'
					+ '<td>' + money_format_india(total_credit_disc_amt || 0) + '</td>'
					+ '<td></td>'
					+ '<td>' + money_format_india(total_old_metal_amount || 0) + '</td>'
					+ '<td>' + money_format_india(Math.max(0, parseFloat(total_bal_amount || 0)).toFixed(2)) + '</td>'
					+ '<td></td>'
				'<td></td>' +
				+ '</tr>';
				$('#credit_issued_list > tbody').html(trHTML);
				// Check and initialise datatable
				if (!$.fn.DataTable.isDataTable('#credit_issued_list')) {
					oTable = $('#credit_issued_list').dataTable({
						"bSort": false,
						"bInfo": true,
						"scrollX": '100%',
						"dom": 'lBfrtip',
						"paging": false,
						"columnDefs": [
							{
								targets: [5, 6, 7, 8, 9, 10],
								className: 'dt-body-right'
							},
						],
						"buttons": [
							{
								extend: 'print',
								footer: true,
								title: '',
								messageTop: title,
								customize: function (win) {
									$(win.document.body).find('table')
										.addClass('compact')
										.css('font-size', '10px');
								},
							},
							{
								extend: 'excel',
								footer: true,
								title: company_name + '-' + (branch_name != '' ? branch_name : '') + ' - ' + report_type + ' ' + dt_range[0] + '-' + dt_range[1],
							}
						],
					});
				}
			}
			$("div.overlay").css("display", "none");
		},
		error: function (error) {
			$("div.overlay").css("display", "none");
		}
	});
}
//credit history
function set_advance_history_table() {
	$("div.overlay").css("display", "block");
	my_Date = new Date();
	$.ajax({
		url: base_url + "index.php/admin_ret_reports/advance_history/ajax?nocache=" + my_Date.getUTCSeconds(),
		data: ({ 'dt_range': $("#dt_range").val(), 'id_branch': $("#branch_select").val() }),
		dataType: "JSON",
		type: "POST",
		success: function (data) {
			var list = data.list;
			if (list != null) {
				trHTML = '';
				tfootHTML = '';
				total_adv_amount = 0;
				total_adjusted_amount = 0;
				$.each(list, function (i, branch) {
					var adv_amount = 0;
					var adjusted_amt = 0;
					$.each(branch, function (idx, item) {
						trHTML += '<tr>' +
							'<td>' + item.branch_name + '</td>'
							+ '<td>' + item.cus_name + '</td>'
							+ '<td>' + item.mobile + '</td>'
							+ '<td>' + item.total_adv_amount + '</td>'
							+ '<td>' + item.adjusted_amt + '</td>'
						'</tr>';
						adv_amount = parseFloat(adv_amount) + parseFloat(item.total_adv_amount);
						adjusted_amt = parseFloat(adjusted_amt) + parseFloat(item.adjusted_amt);
					});
					trHTML += '<tr style="font-weight:bold;">' +
						+ '<td></td>'
						+ '<td></td>'
						+ '<td></td>'
						+ '<td>Sub Total</td>'
						+ '<td>' + adv_amount + '</td>'
						+ '<td>' + adjusted_amt + '</td>'
						+ '</tr>';
					total_adv_amount = total_adv_amount + adv_amount;
					total_adjusted_amount = total_adjusted_amount + adjusted_amt;
				});
				trHTML += '<tr style="font-weight:bold;">' +
					'<td></td>'
					+ '<td></td>'
					+ '<td></td>'
					+ '<td>Grand Total</td>'
					+ '<td>' + total_adv_amount + '</td>'
					+ '<td>' + total_adjusted_amount + '</td>'
				+ '</tr>';
				$('#advance_list > tbody').html(trHTML);
				// Check and initialise datatable
				if (!$.fn.DataTable.isDataTable('#advance_list')) {
					oTable = $('#advance_list').dataTable({
						"bSort": false,
						"bInfo": true,
						"scrollX": '100%',
						"dom": 'lBfrtip',
						"paging": false,
						"buttons": [
							{
								extend: 'print',
								footer: true,
								title: "Advance History Report - " + $("#dt_range").val(),
								customize: function (win) {
									$(win.document.body).find('table')
										.addClass('compact')
										.css('font-size', 'inherit');
								},
							},
							{
								extend: 'excel',
								footer: true,
								title: "Advance History Report - " + $("#dt_range").val(),
							}
						],
					});
				}
			}
			$("div.overlay").css("display", "none");
		},
		error: function (error) {
			$("div.overlay").css("display", "none");
		}
	});
}
function set_chit_closing_table() {
	var dt_range = ($("#dt_range").val()).split('-');
	var company_name = $('#company_name').val();
	var from_date = dt_range[0];
	var to_date = dt_range[1];
	var branch_name = ($('#branch_name').val() != '' && $('#branch_name').val() != undefined ? $('#branch_name').val() : $("#branch_select option:selected").text());
	var report_name = "Chit Closing Report"
	var optional = '';
	var title = "<div style='text-align: center;'><b><span style='font-size:15pt;'>" + company_name + "</span></b><b><span style='font-size:12pt;'></span></b></br>"
		+ "<span>" + report_print(branch_name, report_name, from_date, to_date, optional) + "</span>";
	$("div.overlay").css("display", "block");
	my_Date = new Date();
	$(".overlay").css("display", "block");
	$.ajax({
		url: base_url + "index.php/admin_ret_reports/chit_closing_details/ajax?nocache=" + my_Date.getUTCSeconds(),
		data: ({ 'dt_range': $("#dt_range").val(), 'id_branch': $("#branch_select").val() }),
		dataType: "JSON",
		type: "POST",
		success: function (data) {
			var list = data.list;
			$("#chit_closing_list > tbody > tr").remove();
			$('#chit_closing_list').dataTable().fnClearTable();
			$('#chit_closing_list').dataTable().fnDestroy();
			if (list != null && list.length > 0) {
				trHTML = '';
				tfootHTML = '';
				var total_closing_amount = 0;
				var total_bonus = 0;
				var total_rate_benefits = 0;
				var total_apx_mc_va = 0;
				var total_add_benefits = 0;
				var total_deductions = 0;
				var grand_total = 0;
				$.each(list, function (i, item) {
					var url = base_url + 'index.php/admin_ret_billing/billing_invoice/' + item.bill_id;
					var chit_url = base_url + 'index.php/reports/payment/account/' + item.scheme_account_id;
					var closing_amt = parseFloat(item.closing_amount) || 0;
					var bonus = parseFloat(item.discountAmt) || 0;
					var rate_ben = parseFloat(item.benifits) || 0;
					var apx_mc_va = parseFloat(item.sch_benefits) || 0;
					var add_ben = parseFloat(item.additional_bennefits) || 0;
					var deductions = parseFloat(item.closing_add_chgs) || 0;
					var row_total = closing_amt + bonus + rate_ben + apx_mc_va + add_ben - deductions;
					trHTML += '<tr>'
						+ '<td>' + item.bill_date + '</td>'
						+ '<td><a href=' + url + ' target="_blank">' + item.bill_no + '</a></td>'
						+ '<td>' + item.cus_name + '</td>'
						+ '<td>' + item.mobile + '</td>'
						+ '<td>' + item.scheme_name + '</td>'
						+ '<td><a href=' + chit_url + ' target="_blank">' + item.scheme_acc_number + '</a></td>'
						+ '<td><a href=' + chit_url + ' target="_blank">' + item.scheme_account_id + '</a></td>'
						+ '<td>' + item.paid_installments + '/' + item.total_installments + '</td>'
						+ '<td>' + money_format_india(closing_amt.toFixed(2)) + '</td>'
						+ '<td>' + money_format_india(bonus.toFixed(2)) + '</td>'
						+ '<td>' + money_format_india(rate_ben.toFixed(2)) + '</td>'
						+ '<td>' + money_format_india(apx_mc_va.toFixed(2)) + '</td>'
						+ '<td>' + money_format_india(add_ben.toFixed(2)) + '</td>'
						+ '<td>' + money_format_india(deductions.toFixed(2)) + '</td>'
						+ '<td>' + money_format_india(row_total.toFixed(2)) + '</td>'
						+ '</tr>';
					total_closing_amount += closing_amt;
					total_bonus += bonus;
					total_rate_benefits += rate_ben;
					total_apx_mc_va += apx_mc_va;
					total_add_benefits += add_ben;
					total_deductions += deductions;
					grand_total += row_total;
				});
				trHTML += '<tr style="font-weight:bold;color:blue">'
					+ '<td></td>'
					+ '<td></td>'
					+ '<td></td>'
					+ '<td></td>'
					+ '<td></td>'
					+ '<td></td>'
					+ '<td></td>'
					+ '<td>Grand Total</td>'
					+ '<td>' + money_format_india(parseFloat(total_closing_amount).toFixed(2)) + '</td>'
					+ '<td>' + money_format_india(parseFloat(total_bonus).toFixed(2)) + '</td>'
					+ '<td>' + money_format_india(parseFloat(total_rate_benefits).toFixed(2)) + '</td>'
					+ '<td>' + money_format_india(parseFloat(total_apx_mc_va).toFixed(2)) + '</td>'
					+ '<td>' + money_format_india(parseFloat(total_add_benefits).toFixed(2)) + '</td>'
					+ '<td>' + money_format_india(parseFloat(total_deductions).toFixed(2)) + '</td>'
					+ '<td>' + money_format_india(parseFloat(grand_total).toFixed(2)) + '</td>'
				+ '</tr>';
				$('#chit_closing_list > tbody').html(trHTML);
				// Check and initialise datatable
				if (!$.fn.DataTable.isDataTable('#chit_closing_list')) {
					oTable = $('#chit_closing_list').dataTable({
						"bSort": false,
						"bInfo": true,
						"scrollX": '100%',
						"dom": 'lBfrtip',
						"paging": false,
						"columnDefs": [
							{
								targets: [0, 1, 2, 3, 4, 5, 6, 7],
								className: 'dt-body-left'
							},
							{
								targets: [8, 9, 10, 11, 12, 13, 14],
								className: 'dt-body-right'
							},
						],
						"buttons": [
							{
								extend: 'print',
								footer: true,
								title: '',
								messageTop: title,
								customize: function (win) {
									$(win.document.body)
										.css('font-size', '12pt');
								},
							},
							{
								extend: 'excel',
								footer: true,
								title: "Chit Clsoing Report - " + $("#dt_range").val(),
							}
						],
					});
				}
			}
			$("div.overlay").css("display", "none");
		},
		error: function (error) {
			$("div.overlay").css("display", "none");
		}
	});
}
// Chit Redemption Report with Coin Purchase & Upselling Details
function set_chit_redemption_table() {
	var dt_range = ($("#dt_range").val()).split('-');
	var company_name = $('#company_name').val();
	var from_date = dt_range[0];
	var to_date = dt_range[1];
	var branch_name = ($('#branch_name').val() != '' && $('#branch_name').val() != undefined ? $('#branch_name').val() : $("#branch_select option:selected").text());
	var report_name = "Detailed Chit Redemption Report";
	var optional = '';
	var title = "<div style='text-align: center;'><b><span style='font-size:15pt;'>" + company_name + "</span></b></br>"
		+ "<span>" + report_print(branch_name, report_name, from_date, to_date, optional) + "</span>";
	$("div.overlay").css("display", "block");
	my_Date = new Date();
	var id_branch = ($('#branch_filter').val() != '' && $('#branch_filter').val() != undefined ? $('#branch_filter').val() : $("#branch_select").val());
	$.ajax({
		url: base_url + "index.php/admin_ret_reports/chit_redemption/ajax?nocache=" + my_Date.getUTCSeconds(),
		data: ({
			'id_branch': id_branch,
			'dt_range': $("#dt_range").val()
		}),
		dataType: "JSON",
		type: "POST",
		success: function (data) {
			var list = data.list;
			$("#chit_redemption_list > tbody > tr").remove();
			$('#chit_redemption_list').dataTable().fnClearTable();
			$('#chit_redemption_list').dataTable().fnDestroy();
			if (list != null && list.length > 0) {
				$('#total_count').text(list.length);
				trHTML = '';
				var tot_maturity_amt = 0, tot_maturity_wt = 0;
				var tot_purchase_wt = 0, sum_redemption = 0;
				var tot_upselling_wt = 0, sum_upselling = 0;
				var tot_coin_wt = 0, sum_coin = 0;
				var count = list.length;

				$.each(list, function (i, item) {
					var url = base_url + 'index.php/admin_ret_billing/billing_invoice/' + item.bill_id;
					var maturity_amt = parseFloat(item.maturity_amount) || 0;
					var maturity_wt = parseFloat(item.maturity_weight) || 0;
					var purchase_wt = parseFloat(item.actual_purchase_weight) || 0;
					var redemption_pct = parseFloat(item.redemption_percent) || 0;
					var upselling_wt = parseFloat(item.upselling_weight) || 0;
					var upselling_pct = parseFloat(item.upselling_percent) || 0;
					var coin_wt = parseFloat(item.coin_weight) || 0;
					var coin_pct = parseFloat(item.coin_selling_percent) || 0;

					trHTML += '<tr>'
						+ '<td>' + (i + 1) + '</td>'
						+ '<td class="text-left">' + item.customer_name + '</td>'
						+ '<td class="text-left">' + item.chit_number + '</td>'
						+ '<td class="text-right">' + money_format_india(maturity_amt.toFixed(2)) + '</td>'
						+ '<td class="text-right">' + maturity_wt.toFixed(3) + '</td>'
						+ '<td class="text-right">' + purchase_wt.toFixed(3) + '</td>'
						+ '<td class="text-right">' + redemption_pct.toFixed(2) + '%</td>'
						+ '<td class="text-right">' + upselling_wt.toFixed(3) + '</td>'
						+ '<td class="text-right">' + upselling_pct.toFixed(2) + '%</td>'
						+ '<td class="text-right">' + coin_wt.toFixed(3) + '</td>'
						+ '<td class="text-right">' + coin_pct.toFixed(2) + '%</td>'
						+ '<td><a href=' + url + ' target="_blank">' + item.bill_no + '</a></td>'
						+ '<td>' + (item.transaction_date || '-') + '</td>'
						+ '<td class="text-left">' + item.salesperson + '</td>'
						+ '</tr>';

					tot_maturity_amt += maturity_amt;
					tot_maturity_wt += maturity_wt;
					tot_purchase_wt += purchase_wt;
					sum_redemption += redemption_pct;
					tot_upselling_wt += upselling_wt;
					sum_upselling += upselling_pct;
					tot_coin_wt += coin_wt;
					sum_coin += coin_pct;
				});

				// Summary footer row
				trHTML += '<tr style="font-weight:bold;color:blue">'
					+ '<td></td>'
					+ '<td></td>'
					+ '<td class="text-right"><b>Total</b></td>'
					+ '<td class="text-right">' + money_format_india(tot_maturity_amt.toFixed(2)) + '</td>'
					+ '<td class="text-right">' + tot_maturity_wt.toFixed(3) + '</td>'
					+ '<td class="text-right">' + tot_purchase_wt.toFixed(3) + '</td>'
					+ '<td class="text-right">' + (count > 0 ? (sum_redemption / count).toFixed(2) : '0.00') + '%</td>'
					+ '<td class="text-right">' + tot_upselling_wt.toFixed(3) + '</td>'
					+ '<td class="text-right">' + (count > 0 ? (sum_upselling / count).toFixed(2) : '0.00') + '%</td>'
					+ '<td class="text-right">' + tot_coin_wt.toFixed(3) + '</td>'
					+ '<td class="text-right">' + (count > 0 ? (sum_coin / count).toFixed(2) : '0.00') + '%</td>'
					+ '<td></td>'
					+ '<td></td>'
					+ '<td></td>'
					+ '</tr>';

				$('#chit_redemption_list > tbody').html(trHTML);
				if (!$.fn.DataTable.isDataTable('#chit_redemption_list')) {
					oTable = $('#chit_redemption_list').dataTable({
						"bSort": false,
						"bInfo": true,
						"scrollX": '100%',
						"dom": 'lBfrtip',
						"paging": false,
						"columnDefs": [
							{
								targets: [0, 1, 2, 11, 12, 13],
								className: 'dt-body-left'
							},
							{
								targets: [3, 4, 5, 6, 7, 8, 9, 10],
								className: 'dt-body-right'
							},
						],
						"buttons": [
							{
								extend: 'print',
								footer: true,
								title: '',
								messageTop: title,
								customize: function (win) {
									$(win.document.body)
										.css('font-size', '11pt');
									$(win.document.body).find('table')
										.addClass('compact')
										.css('font-size', 'inherit');
								},
							},
							{
								extend: 'excel',
								footer: true,
								title: "Chit Redemption Report - " + $("#dt_range").val(),
							}
						],
					});
				}
			} else {
				$('#total_count').text('0');
			}
			$("div.overlay").css("display", "none");
		},
		error: function (error) {
			$("div.overlay").css("display", "none");
		}
	});
}
