function set_order_advance() {
	var dt_range = ($("#dt_range").val()).split('-');
	var from_date = dt_range[0];
	var to_date = dt_range[1];
	var branch_name = $("#branch_select option:selected").text();
	var company_name = $('#company_name').val();
	var title = "<b><span style='font-size:15pt;margin-left:50%;'>" + company_name + "</span></b><b><span style='font-size:15pt;'></span></b></br>" + "<span style=font-size:13pt;margin-left:25%;>&nbsp;&nbsp;Order Advance Details " + ($("#branch_select").val() != '' ? "Cost Center:" + branch_name + " " : '') + "</span>";
	$("div.overlay").css("display", "block");
	my_Date = new Date();
	$.ajax({
		url: base_url + "index.php/admin_ret_reports/order_advance/ajax?nocache=" + my_Date.getUTCSeconds(),
		data: ({ 'id_branch': $("#branch_filter").val(), 'dt_range': $("#dt_range").val(), 'filter_by': $("#filterby").val() }),
		dataType: "JSON",
		type: "POST",
		success: function (data) {
			$("div.overlay").css("display", "none");
			var list = data.list;
			var oTable = $('#adv_list').DataTable();
			oTable.clear().draw();
			if (list != null && list.length > 0) {
				oTable = $('#adv_list').dataTable({
					"bDestroy": true,
					"bInfo": true,
					"bFilter": true,
					"order": [[0, "desc"]],
					"scrollX": '100%',
					"bSort": true,
					"dom": 'lBfrtip',
					"columnDefs": [
						{
							targets: [6, 7, 8, 9, 10, 11],
							className: 'dt-right'
						},
						{
							targets: [0, 1, 2, 3, 4, 5, 12],
							className: 'dt-left'
						},
					],
					"buttons": [
						{
							extend: 'print',
							footer: true,
							title: title,
							customize: function (win) {
								$(win.document.body).find('table')
									.addClass('compact')
									.css('font-size', 'inherit');
							},
						},
						{
							extend: 'excel',
							footer: true,
							title: title,
						}
					],
					"aaData": list,
					"aoColumns": [
						{ "mDataProp": "branch_name" },
						{
							"mDataProp": function (row, type, val, meta) {
								var url = base_url + 'index.php/admin_ret_billing/billing_invoice/' + row.bill_id;
								return '<a href=' + url + ' target="_blank">' + row.bill_no + '</a>';
							}
						},
						{ "mDataProp": "bill_date" },
						{ "mDataProp": "cus_name" },
						{ "mDataProp": "mobile" },
						{ "mDataProp": "order_no" },
						{
							"mDataProp": function (row, type, val, meta) {
								return money_format_india(parseFloat(row.advance_amount).toFixed(2));
							}
						},
						{
							"mDataProp": function (row, type, val, meta) {
								var weight = parseFloat(row.advance_weight);
								if (isNaN(weight)) {
									weight = 0;
								}
								return money_format_india(parseFloat(weight).toFixed(3));
							}
						},
						{
							"mDataProp": function (row, type, val, meta) {
								return money_format_india(parseFloat(row.rate_per_gram).toFixed(2));
							}
						},
						{
							"mDataProp": function (row, type, val, meta) {
								return money_format_india(parseFloat(row.order_value).toFixed(2));
							}
						},
						{
							"mDataProp": function (row, type, val, meta) {
								return money_format_india(parseFloat(row.total_order_adv).toFixed(2));
							}
						},
						{
							"mDataProp": function (row, type, val, meta) {
								var adv_percent = 0;
								if(row.order_value > 0){
									adv_percent = (row.total_order_adv / row.order_value) * 100;
								}
								adv_percent = adv_percent.toFixed(2);
								var color = adv_percent > 80 ? 'blue' : 'red';
								var fontSize = '14px';
								return '<span style="font-weight: bold; color: ' + color + '; font-size: ' + fontSize + ';">' + adv_percent + '%</span>';
							}
						},
						{ "mDataProp": "bill_status" }
					],
					"footerCallback": function (row, data, start, end, display) {
						var api = this.api();
						if (list.length > 0) {
							var intVal = function (i) {
								return typeof i === 'string' ?
									i.replace(/[\$,]/g, '') * 1 :
									typeof i === 'number' ?
										i : 0;
							};

							// Helper to sum a column
							var sumCol = function(colIndex) {
								return api
									.column(colIndex)
									.data()
									.reduce(function (a, b) {
										// If formatting function is used, a/b might be objects/strings? 
										// .data() returns the original data object if mData is function? 
										// Wait, DataTables .data() on column returns the RENDERED data if text based? 
										// Actually if mData is function, data() returns the result of the function?
										// Let's safe parse. 
										// Actually better to use the original JSON data if possible, but here we iterate rendered?
										// API column().data() returns the data for the column. If mData is function, it returns the function result.
										return intVal(a) + intVal(b);
									}, 0);
							};
							
							// For robust summing with mData functions, we might need to access the underlying data source if possible, but checking current implementation...
							// The previous implementation used reduce on .data().
							// Since we changed mData to return formatted strings, we need to strip commas. intVal does that.
							
							var advance_amount = sumCol(6);
							var advance_weight = sumCol(7);
							var rate = sumCol(8); 
							var order_value = sumCol(9);
							var total_advance = sumCol(10);

							$(api.column(0).footer()).html('Grand Total');
							$(api.column(6).footer()).html(money_format_india(parseFloat(advance_amount).toFixed(2)));
							$(api.column(7).footer()).html(money_format_india(parseFloat(advance_weight).toFixed(3)));
							$(api.column(8).footer()).html(money_format_india(parseFloat(rate).toFixed(2)));
							$(api.column(9).footer()).html(money_format_india(parseFloat(order_value).toFixed(2)));
							$(api.column(10).footer()).html(money_format_india(parseFloat(total_advance).toFixed(2)));
							$(api.column(11).footer()).html('');
							$(api.column(12).footer()).html('');
						} else {
							$(api.column(0).footer()).html('Grand Total');
							$(api.column(6).footer()).html('');
							$(api.column(7).footer()).html('');
							$(api.column(8).footer()).html('');
							$(api.column(9).footer()).html('');
							$(api.column(10).footer()).html('');
							$(api.column(11).footer()).html('');
							$(api.column(12).footer()).html('');
						}
					}
				});
			}
		},
		error: function (error) {
			$("div.overlay").css("display", "none");
		}
	});
}
