$('#id_report_type').on('change', function () {
	$('.ref_list_sum').css("display", "none");
	$('.ref_list_det').css("display", "none");
	if (this.value == 2) {
		$('.ref_list_sum').css("display", "block");
	} else {
		$('.ref_list_det').css("display", "block");
	}
});
