//Sales Comparision
function get_sales_comparision() {
	const monthNames = ["", "Jan", "Feb", "Mar", "Apr", "May", "Jun",
		"Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
	var chart_details = getMonthlySalesDetails();
	var line = new Morris.Line
		({
			element: 'sales_chart',
			data: chart_details.pro_details,
			xkey: 'x',
			parseTime: false,
			ykeys: ['y'],
			xLabelFormat: function (x) {
				console.log(x);
				var index = parseInt(x.src.x);
				return monthNames[index];
			},
			xLabels: "month",
			labels: ['Weight'],
			lineColors: ['#a0d0e0', '#3dbeee'],
			hideHover: 'auto'
		});
	Morris.Donut({
		element: 'metal_chart',
		data: chart_details.metal_details,
		series: {
			pie: {
				show: false,
				radius: 1,
				innerRadius: 0.5,
				resize: false,
				label: {
					show: false,
					radius: 2 / 3,
					formatter: labelFormatter,
					threshold: 0.1
				}
			}
		},
		legend: {
			show: false
		}
	});
}
function labelFormatter(label, series) {
	return '<div style="font-size:13px; text-align:center; padding:2px; color: #fff; font-weight: 600;">'
		+ label
		+ '<br>'
		+ Math.round(series.percent) + '%</div>'
}
function getMonthlySalesDetails() {
	my_Date = new Date();
	var data = "";
	$.ajax({
		type: 'POST',
		url: base_url + "index.php/admin_ret_reports/sales_comparision/ajax?nocache=" + my_Date.getUTCSeconds(),
		dataType: 'json',
		async: false,
		data: { 'id_product': $('#prod_select').val() },
		success: function (result) {
			data = result;
		},
		error: function (xhr, status, error) {
			console.log(error);
		}
	});
	return data;
}
