// Verify payment button click handler - instant update without page reload
$(document).on('click', '.btn-verify', function () {
	var btn = $(this);
	var pay_id = btn.data('payid');
	btn.prop('disabled', true).html('<i class="fa fa-spinner fa-spin"></i>');
	$.ajax({
		url: base_url + "index.php/admin_ret_reports/popayments/verify",
		data: { 'pay_id': pay_id },
		type: "POST",
		dataType: "JSON",
		success: function (data) {
			if (data.status == 'success') {
				btn.replaceWith('<span class="label label-success">Verified</span>');
				$.toaster({ priority: 'success', title: 'Success', message: 'Payment verified successfully!' });
			} else {
				btn.prop('disabled', false).html('<i class="fa fa-check"></i> Verify');
				$.toaster({ priority: 'danger', title: 'Error', message: 'Failed to verify payment.' });
			}
		},
		error: function (error) {
			btn.prop('disabled', false).html('<i class="fa fa-check"></i> Verify');
			$.toaster({ priority: 'danger', title: 'Error', message: 'Failed to verify payment.' });
		}
	});
});
