//Supplier Approval Ledger
$('#supplier_approval_ledger_search').on('click', function () {
	get_SupplierApprovalTransactions();
});
function sal_fmt_wt(val) {
	var num = parseFloat(val);
	if (isNaN(num) || num === 0) return '';
	return money_format_india(num.toFixed(3));
}
function sal_fmt_amt(val, decimals) {
	decimals = (typeof decimals === 'undefined') ? 2 : decimals;
	var num = parseFloat(val);
	if (isNaN(num) || num === 0) return '';
	return money_format_india(num.toFixed(decimals));
}
function sal_fmt_int(val) {
	var num = parseInt(val);
	if (isNaN(num) || num === 0) return '';
	return num;
}
function sal_blank_if_zero(formatted) {
	var num = parseFloat(String(formatted).replace(/,/g, ''));
	if (!isNaN(num) && num === 0) return '';
	return formatted;
}
function sal_hide_pcs() {
	return (typeof SAL_HIDE_PCS !== 'undefined' && SAL_HIDE_PCS === true);
}
function sal_hide_gwt() {
	return (typeof SAL_HIDE_GWT !== 'undefined' && SAL_HIDE_GWT === true);
}
function sal_hide_nwt() {
	return (typeof SAL_HIDE_NWT !== 'undefined' && SAL_HIDE_NWT === true);
}
function sal_col(html, hidden) {
	return hidden ? '' : html;
}
