if (ctrl_page[1] == 'item_sales_detail' || ctrl_page[1] == 'reorder_items') {
	$("#emp_sel,#des_select,#metal,#category,#section_select,#prod_select").attr('multiple', 'multiple');
	$("#emp_sel,#des_select,#metal,#category,#section_select,#prod_select").select2({
		allowClear: true,
		multiple: true    , 
	});
	$.ajax({
		url: base_url + "index.php/admin_ret_estimation/get_employee?nocache=",
		type: "POST",
		dataType: "JSON",
		success: function (data) {
			$.each(data, function (key, item) {
				$("#emp_sel").append(
					$("<option></option>")
						.attr("value", item.id_employee)
						.text(item.emp_name)
				);
			});
			$("#emp_sel").trigger('change');  // refresh select2 UI
		}
	});
}


