var PRESETS = {
  default:  COL_MAP.map(function(c){ return {key:c.key,visible:c.visible}; }),
  customer: ['branch','bill_no','bill_date','cus_name','cus_address','state_name','gst_number','product_name','purity','gross_wt','net_wt','total_cost'],
  weight:   ['branch','bill_no','bill_date','tag_code','section_name','purity','product_name','tot_pcs','gross_wt','less_wt','net_wt','dia_wt','tag_gross_wt','diff_wt','wastage_percent','wast_wgt'],
  finance:  ['branch','bill_no','bill_date','cus_name','purity','tot_pcs','mc_value','amt_without_tax','total_cgst','total_sgst','total_igst','total_cost','stn_amt'],
};

var STORAGE_KEY        = 'itemwise_col_cfg_v2';
var CUSTOM_PRESET_KEY  = 'itemwise_custom_presets';

// ── Summary report column map ────────────────────────────────────────────────
var SUMMARY_COL_MAP = [
  {key:'section_name',    label:'Section',       visible:true,  numeric:false},
  {key:'purity',          label:'Purity',        visible:true,  numeric:false},
  {key:'tagcount',        label:'Tags',          visible:true,  numeric:true},
  {key:'tot_pcs',         label:'Pcs',           visible:true,  numeric:true},
  {key:'gross_wt',        label:'Gwt (g)',       visible:true,  numeric:true},
  {key:'diawt',           label:'Dia Wt (g)',    visible:true,  numeric:true},
  {key:'dia_amt',         label:'Dia Amt (₹)',   visible:true,  numeric:true},
  {key:'net_wt',          label:'Nwt (g)',       visible:true,  numeric:true},
  {key:'tag_gross_wt',    label:'TAG Gwt (g)',   visible:true,  numeric:true},
  {key:'diff_wt',         label:'Diff Wt (g)',   visible:true,  numeric:true},
  {key:'wastage_percent', label:'Wastage (%)',   visible:false, numeric:true},
  {key:'wast_wt',         label:'Wastage (g)',   visible:false, numeric:true},
  {key:'mc_value',        label:'MC (₹)',        visible:false, numeric:true},
  {key:'total_cost',      label:'Amount (₹)',    visible:false, numeric:true},
  {key:'stn_amt',         label:'Stn Amt (₹)',   visible:true,  numeric:true},
];
var SUMMARY_PRESETS = {
  default: SUMMARY_COL_MAP.map(function(c){ return {key:c.key, visible:c.visible}; }),
};
var SUMMARY_STORAGE_KEY       = 'itemwise_summary_col_cfg_v2';
var SUMMARY_CUSTOM_PRESET_KEY = 'itemwise_summary_custom_presets';
var activeReportMode          = 'detail'; // 'detail' | 'summary'
function loadColCfg() {
  try {
    var s = localStorage.getItem(STORAGE_KEY);
    var stored = s ? JSON.parse(s) : null;
    if (!stored) return null;
    // Auto-merge: new keys added to COL_MAP get appended (use configured default visibility)
    COL_MAP.forEach(function(def) {
      if (!stored.find(function(c){ return c.key === def.key; })) {
        stored.push({ key: def.key, visible: def.visible });
      }
    });
    // Auto-purge: remove stale keys that no longer exist in COL_MAP
    stored = stored.filter(function(c){
      return COL_MAP.find(function(def){ return def.key === c.key; });
    });
    return stored;
  } catch(e) { return null; }
}
function saveColCfg(cfg) { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(cfg)); } catch(e){} }
function loadCustomPresets() { try { var s = localStorage.getItem(CUSTOM_PRESET_KEY); return s ? JSON.parse(s) : {}; } catch(e){return {};} }
function saveCustomPresets(p) { try { localStorage.setItem(CUSTOM_PRESET_KEY, JSON.stringify(p)); } catch(e){} }

// ── Summary storage helpers ──────────────────────────────────────────────────
function loadSummaryCfg() {
  try {
    var s = localStorage.getItem(SUMMARY_STORAGE_KEY);
    var stored = s ? JSON.parse(s) : null;
    if (!stored) return null;
    SUMMARY_COL_MAP.forEach(function(def) {
      if (!stored.find(function(c){ return c.key === def.key; })) {
        stored.push({ key: def.key, visible: def.visible });
      }
    });
    stored = stored.filter(function(c){
      return SUMMARY_COL_MAP.find(function(def){ return def.key === c.key; });
    });
    return stored;
  } catch(e) { return null; }
}
function saveSummaryCfg(cfg) { try { localStorage.setItem(SUMMARY_STORAGE_KEY, JSON.stringify(cfg)); } catch(e){} }
function loadSummaryCustomPresets() { try { var s = localStorage.getItem(SUMMARY_CUSTOM_PRESET_KEY); return s ? JSON.parse(s) : {}; } catch(e){return {};} }
function saveSummaryCustomPresets(p) { try { localStorage.setItem(SUMMARY_CUSTOM_PRESET_KEY, JSON.stringify(p)); } catch(e){} }

var activeCfg        = loadColCfg()     || PRESETS.default.slice();
var activeSummaryCfg = loadSummaryCfg() || SUMMARY_PRESETS.default.slice();
var activePresetKey  = null; // which preset pill is currently applied

// Modal logic
$(document).ready(function(){
  var dragSrc = null;
  var workingCfg = []; // safe working clone — only applied on "Apply & Save"

  // ── Mode-aware helpers ──────────────────────────────────────────────────────
  function activeColMap()   { return activeReportMode === 'summary' ? SUMMARY_COL_MAP   : COL_MAP; }
  function activePresetSet(){ return activeReportMode === 'summary' ? SUMMARY_PRESETS   : PRESETS; }
  function getActiveCfg()   { return activeReportMode === 'summary' ? activeSummaryCfg  : activeCfg; }
  function saveActiveCfg(cfg) {
    if (activeReportMode === 'summary') { activeSummaryCfg = cfg; saveSummaryCfg(cfg); }
    else                               { activeCfg        = cfg; saveColCfg(cfg); }
  }
  function loadActiveCustomPresets() {
    return activeReportMode === 'summary' ? loadSummaryCustomPresets() : loadCustomPresets();
  }
  function saveActiveCustomPresets(p) {
    if (activeReportMode === 'summary') saveSummaryCustomPresets(p);
    else saveCustomPresets(p);
  }

  function buildModalList(cfg) {
    var $list = $('#col-sort-list').empty();
    var colMap = activeColMap();
    // Update visible count badge in drawer header
    var visCount = cfg.filter(function(c){ return c.visible; }).length;
    $('#colVisBadge').text(visCount + ' / ' + cfg.length + ' visible');

    cfg.forEach(function(c, idx){
      var def = colMap.find(function(d){return d.key===c.key;});
      if(!def) return;
      var visClass = c.visible ? '' : 'hidden-col-row';
      var eyeIcon  = c.visible ? '👁' : '🚫';
      var $li = $('<li draggable="true">')
        .addClass(visClass)
        .attr('data-key', c.key)
        .html(
          '<span class="drag-handle">⠿</span>'+
          '<span class="col-badge">'+(idx+1)+'</span>'+
          '<span class="col-name">'+ def.label +'</span>'+
          '<button class="visibility-toggle '+(c.visible?'':'hidden-col')+'" title="Toggle visibility">'+ eyeIcon +'</button>'
        );
      $li.find('.visibility-toggle').on('click', function(){
        c.visible = !c.visible;
        buildModalList(cfg);
      });
      $li[0].addEventListener('dragstart', function(e){
        dragSrc = this; $(this).addClass('dragging');
        e.dataTransfer.effectAllowed = 'move';
      });
      $li[0].addEventListener('dragend', function(){
        $(this).removeClass('dragging');
        $('#col-sort-list li').removeClass('drag-over');
      });
      $li[0].addEventListener('dragover', function(e){
        e.preventDefault(); e.dataTransfer.dropEffect = 'move';
        $('#col-sort-list li').removeClass('drag-over');
        if (this !== dragSrc) $(this).addClass('drag-over');
        return false;
      });
      $li[0].addEventListener('drop', function(e){
        e.stopPropagation();
        if (this === dragSrc) return false;
        var fromKey = $(dragSrc).data('key');
        var toKey   = $(this).data('key');
        var fromIdx = cfg.findIndex(function(x){return x.key===fromKey;});
        var toIdx   = cfg.findIndex(function(x){return x.key===toKey;});
        var moved   = cfg.splice(fromIdx, 1)[0];
        cfg.splice(toIdx, 0, moved);
        buildModalList(cfg);
        return false;
      });
      $list.append($li);
    });
  }

  // ── Render preset pills (built-in + custom) ──────────────────────────────
  function renderPresets(highlightKey) {
    var $row = $('.preset-row').empty();
    var customPresets = loadActiveCustomPresets();

    // Built-in presets — summary only has Default; detail has 4
    var builtins = activeReportMode === 'summary'
      ? [{key:'default', label:'Default'}]
      : [
          {key:'default',  label:'Default'},
          {key:'customer', label:'Customer View'},
          {key:'weight',   label:'Weight View'},
          {key:'finance',  label:'Finance View'},
        ];
    builtins.forEach(function(b){
      var $btn = $('<button class="preset-btn" data-preset="'+b.key+'">'+b.label+'</button>');
      if (highlightKey === b.key) $btn.addClass('active');
      $btn.on('click', function(){ applyPreset(b.key); });
      $row.append($btn);
    });

    // Custom presets
    Object.keys(customPresets).forEach(function(name){
      var safeKey = 'custom__' + name;
      var $btn = $('<button class="preset-btn preset-custom" data-preset="'+safeKey+'">')
        .text(name);
      if (highlightKey === safeKey) $btn.addClass('active');
      var $del = $('<span class="preset-del" title="Delete this view">&times;</span>');
      $del.on('click', function(e){
        e.stopPropagation();
        var cp = loadActiveCustomPresets();
        delete cp[name];
        saveActiveCustomPresets(cp);
        if (activePresetKey === safeKey) activePresetKey = null;
        renderPresets(activePresetKey);
      });
      $btn.append($del);
      $btn.on('click', function(){ applyPreset(safeKey); });
      $row.append($btn);
    });

    // + Save View button
    var $addBtn = $('<button class="preset-btn preset-add-btn" id="saveNewView" title="Save current layout as a new view">&#43; Save View</button>');
    $addBtn.on('click', function(){
      if ($('#newViewInput').length) { $('#newViewInput').remove(); return; }
      var $wrap = $('<span id="newViewInput" style="display:inline-flex;align-items:center;gap:4px;">');
      var $inp  = $('<input type="text" placeholder="View name..." maxlength="20" style="font-size:11px;padding:3px 7px;border:1px solid #bce8f1;border-radius:10px;outline:none;width:110px;">');
      var $ok   = $('<button style="font-size:11px;padding:3px 8px;background:#3c8dbc;color:#fff;border:none;border-radius:10px;cursor:pointer;">Save</button>');
      $ok.on('click', function(){
        var name = $.trim($inp.val());
        if (!name) { $inp.focus(); return; }
        var cp = loadActiveCustomPresets();
        cp[name] = workingCfg.map(function(c){ return {key:c.key, visible:c.visible}; });
        saveActiveCustomPresets(cp);
        activePresetKey = 'custom__' + name;
        renderPresets(activePresetKey);
      });
      $inp.on('keydown', function(e){ if(e.which===13) $ok.trigger('click'); if(e.which===27) $wrap.remove(); });
      $wrap.append($inp).append($ok);
      $row.append($wrap);
      setTimeout(function(){ $inp.focus(); }, 50);
    });
    $row.append($addBtn);
  }

  // ── Apply a named preset to workingCfg ────────────────────────────────────
  function applyPreset(presetKey) {
    activePresetKey = presetKey;
    var colMap = activeColMap();
    var customPresets = loadActiveCustomPresets();
    var keys;
    if (presetKey.indexOf('custom__') === 0) {
      var name = presetKey.replace('custom__', '');
      keys = customPresets[name] || [];
      workingCfg = keys.map(function(c){ return {key:c.key, visible:c.visible}; });
      colMap.forEach(function(def){
        if (!workingCfg.find(function(c){ return c.key===def.key; })) {
          workingCfg.push({key:def.key, visible:false});
        }
      });
    } else {
      var preset = activePresetSet()[presetKey];
      if (Array.isArray(preset) && typeof preset[0] === 'string') {
        workingCfg = preset.map(function(k){ return {key:k, visible:true}; });
        colMap.forEach(function(def){
          if (!workingCfg.find(function(c){ return c.key===def.key; })) {
            workingCfg.push({key:def.key, visible:false});
          }
        });
      } else {
        workingCfg = preset.map(function(c){ return {key:c.key, visible:c.visible}; });
      }
    }
    renderPresets(activePresetKey);
    buildModalList(workingCfg);
  }

  // ── Detect which preset (if any) matches a cfg ───────────────────────────
  function detectPreset(cfg) {
    var colMap = activeColMap();
    var customPresets = loadActiveCustomPresets();
    // Check custom first
    for (var name in customPresets) {
      var cp = customPresets[name];
      var match = cp.length === cfg.length && cp.every(function(c, i){
        return cfg[i] && cfg[i].key === c.key && cfg[i].visible === c.visible;
      });
      if (match) return 'custom__' + name;
    }
    // Check built-ins
    var presetSet = activePresetSet();
    var builtinKeys = Object.keys(presetSet);
    for (var i = 0; i < builtinKeys.length; i++) {
      var pk = builtinKeys[i];
      var preset = presetSet[pk];
      var refCfg;
      if (Array.isArray(preset) && typeof preset[0] === 'string') {
        refCfg = preset.map(function(k){ return {key:k, visible:true}; });
        colMap.forEach(function(def){
          if (!refCfg.find(function(c){ return c.key===def.key; })) refCfg.push({key:def.key, visible:false});
        });
      } else {
        refCfg = preset;
      }
      var isMatch = refCfg.length === cfg.length && refCfg.every(function(c, j){
        return cfg[j] && cfg[j].key === c.key && cfg[j].visible === c.visible;
      });
      if (isMatch) return pk;
    }
    return null;
  }

  // Open: clone active cfg into workingCfg (mode-aware)
  $('#openColManager').on('click', function(){
    var cfg = getActiveCfg();
    workingCfg = cfg.map(function(c){ return {key:c.key, visible:c.visible}; });
    renderPresets(detectPreset(cfg));
    buildModalList(workingCfg);
    $('#colManagerModal').addClass('show');
  });

  // Close/Cancel: discard workingCfg — activeCfg unchanged
  $('#closeModal, #colManagerModal').on('click', function(e){
    if (e.target === this) $('#colManagerModal').removeClass('show');
  });

  // Reset: revert workingCfg to mode-aware defaults
  $('#resetCols').on('click', function(){
    var defaultPreset = activePresetSet().default;
    workingCfg = defaultPreset.map(function(c){ return Object.assign({}, c); });
    activePresetKey = 'default';
    renderPresets('default');
    buildModalList(workingCfg);
  });

  // Apply: commit workingCfg → active cfg, save, rebuild correct table
  $('#applyColOrder').on('click', function(){
    saveActiveCfg(workingCfg.slice());
    $('#colManagerModal').removeClass('show');
    itemwise_sales_detail(); // handles both modes via sales_report_type
  });

  // ── Render column headers on page load (both tables) ──────────────────────
  (function renderInitialHeaders(){
    // Detail table
    if ($('#itemwise-sales_detail').length) {
      var visDetail = activeCfg.map(function(c){
        var def = COL_MAP.find(function(d){ return d.key === c.key; });
        return (def && c.visible) ? def : null;
      }).filter(Boolean);
      $('#itemwise-sales_detail > thead').html(
        '<tr>' + visDetail.map(function(c){ return '<th>' + c.label + '</th>'; }).join('') + '</tr>'
      );
    }
    // Summary table
    if ($('#sales_summary_report').length) {
      var visSummary = activeSummaryCfg.map(function(c){
        var def = SUMMARY_COL_MAP.find(function(d){ return d.key === c.key; });
        return (def && c.visible) ? def : null;
      }).filter(Boolean);
      $('#sales_summary_report > thead').html(
        '<tr>' + visSummary.map(function(c){ return '<th>' + c.label + '</th>'; }).join('') + '</tr>'
      );
    }
  })();
});
// ═══════════════════════════════════════════════════════
function itemwise_sales_detail() {

	// var dt_range = ($("#dt_range").val()).split('-');

	var company_name = $('#company_name').val();

	// var from_date = dt_range[0];

	// var to_date = dt_range[1];
	var FromDt = $('#rpt_from_date').html();
	var ToDt = $('#rpt_to_date').html();
	var branch_name = ($('#branch_name').val() != '' && $('#branch_name').val() != undefined ? $('#branch_name').val() : $("#branch_select option:selected").text());
	var report_name = "Product Wise Sales Report";
	var metal = $('#metal option:selected').html() != '' && $('#metal option:selected').html() != undefined ? $('#metal option:selected').html() + ' - ' : '';
	var category = $('#category option:selected').html() != '' && $('#category option:selected').html() != undefined ? $('#category option:selected').html() + ' - ' : '';
	var prod_select = $('#prod_select option:selected').html() != '' && $('#prod_select option:selected').html() != undefined ? $('#prod_select option:selected').html() + ' - ' : '';
	var optional = metal + category + prod_select;
	var title = "<div style='text-align: center;'><b><span style='font-size:15pt;'>" + company_name + "</span></b><b><span style='font-size:12pt;'></span></b></br>"

		+ "<span>" + report_print(branch_name, report_name, FromDt, ToDt, optional) + "</span>";

	var tag_type = $("input[name='tag_or_nontag']:checked").val();
	$("div.overlay").css("display", "block");
	my_Date = new Date();
	$(".overlay").css("display", "block");
	$.ajax({
		type: 'POST',
		url: base_url + "index.php/admin_ret_reports/item_sales_detail/ajax?nocache=" + my_Date.getUTCSeconds(),

		data: ({ 'FromDt': FromDt, 'ToDt': $('#rpt_to_date').html() , 'id_branch': ($('#branch_filter').val() != '' && $('#branch_filter').val() != undefined ? $('#branch_filter').val() : $("#branch_select").val()), 'id_product': $('#prod_select').val(), 'id_category': $('#category').val(), 'id_metal': $('#metal').val(), 'id_section': $('#section_select').val(), 'tag_type': tag_type, 'sales_report_type': $('#sales_report_type').val() , 'huid': $('#tag_huid').val(), 'design_id': $('#des_select').val(), 'id_sub_design': $('#sub_des_select').val(), 'id_employee': $('#emp_sel').val()}),
		dataType: 'json', 
		success: function (data) {
			$(".overlay").css("display", "none");
			var list = data.list;

			if ($('#sales_report_type').val() == 2) {
				if (list != null) {

                    // Destroy any existing DataTable instance FIRST to clear cached column state
                    if ($.fn.DataTable.isDataTable('#itemwise-sales_detail')) {
                        $('#itemwise-sales_detail').DataTable().destroy();
                    }

                    // Wipe DOM rows completely
					$('#itemwise-sales_detail > tbody').empty();

                    // Resolve ordered columns from activeCfg
                    var ordered = activeCfg.map(function(c){
                        var def = COL_MAP.find(function(d){return d.key===c.key;});
                        return def ? Object.assign({}, def, {visible: c.visible}) : null;
                    }).filter(Boolean);

                    // Rebuild <thead> with only visible columns — completely replace to avoid stale <th> count
                    var visibleOrdered = ordered.filter(function(c){ return c.visible; });
                    var headerHtml = '<tr>' + visibleOrdered.map(function(c){
                        return '<th>'+ c.label +'</th>';
                    }).join('') + '</tr>';
                    $('#itemwise-sales_detail > thead').html(headerHtml);

                    var trHtml = '';
                    var grand_totals = {};
                    ordered.forEach(function(c) { grand_totals[c.key] = 0; });

					$.each(list, function (s, section) {
                        var section_totals = {};
                        ordered.forEach(function(c) { section_totals[c.key] = 0; });

                        // Section Header Row
						trHtml += '<tr style="font-weight:bold;">';
                        var firstCol = true;
                        ordered.forEach(function(c) {
                            if (!c.visible) return;
                            if (firstCol) { trHtml += '<td>' + s + '</td>'; firstCol = false; }
                            else { trHtml += '<td></td>'; }
                        });
                        trHtml += '</tr>';

						$.each(section, function (key, items) {
                            // Accumulate exact fields like the old code
                            if(items.tot_pcs) section_totals['tot_pcs'] += parseFloat(items.tot_pcs);
                            if(items.gross_wt) section_totals['gross_wt'] += parseFloat(items.gross_wt);
                            if(items.less_wt) section_totals['less_wt'] += parseFloat(items.less_wt);
                            if(items.net_wt) section_totals['net_wt'] += parseFloat(items.net_wt);
                            if(items.dia_wt) section_totals['dia_wt'] += parseFloat(items.dia_wt);
                            if(items.dia_amt) section_totals['dia_amt'] += parseFloat(items.dia_amt);
                            if(items.tag_gross_wt) section_totals['tag_gross_wt'] += parseFloat(items.tag_gross_wt);
                            section_totals['diff_wt'] += (items.tag_gross_wt > 0 ? parseFloat(items.tag_gross_wt) - parseFloat(items.gross_wt) : 0);
                            if(items.wastage_percent) section_totals['wastage_percent'] += parseFloat(items.wastage_percent);
                            if(items.wast_wgt) section_totals['wast_wgt'] += parseFloat(items.wast_wgt);
                            if(items.mc_value) section_totals['mc_value'] += parseFloat(items.mc_value);
                            if(items.amt_without_tax) section_totals['amt_without_tax'] += parseFloat(items.amt_without_tax);
                            if(items.total_cgst) section_totals['total_cgst'] += parseFloat(items.total_cgst);
                            if(items.total_sgst) section_totals['total_sgst'] += parseFloat(items.total_sgst);
                            if(items.total_igst) section_totals['total_igst'] += parseFloat(items.total_igst);
                            if(items.estimation_rate) section_totals['estimation_rate'] += parseFloat(items.estimation_rate);
                            if(items.total_cost) section_totals['total_cost'] += parseFloat(items.total_cost);
                            if(items.stn_amt) section_totals['stn_amt'] += parseFloat(items.stn_amt);

							var url = base_url + 'index.php/admin_ret_billing/billing_invoice/' + items.bill_id;
							if (items.tag_image != null && items.tag_image != undefined && items.tag_image != '') {
								var img_src = base_url + 'assets/img/tag/' + items.tag_image;
							} else {
								var img_src = base_url + 'assets/img/no_image.png';
							}
							let estimate_url = "";
							if (items.esti_no > 0) {
								estimate_url = '<a href="' + base_url + 'index.php/admin_ret_estimation/generate_invoice/' + items.esti_id + '" target="_blank">' + items.esti_no + '</a>';
							}

                            // Dynamic value mapper
                            items.diff_wt = (parseFloat(items.tag_gross_wt) > 0 ? parseFloat(parseFloat(items.tag_gross_wt) - parseFloat(items.gross_wt)).toFixed(3) : '0.000');
                            items.bill_no = '<a href=' + url + ' target="_blank">' + items.bill_no + '</a>';
                            items.esti_no = estimate_url;
                            items.tag_image = '<img class="img_src" id="img_prev" src="' + img_src + '" width="35" height="35" onclick="tag_imgprev($(this).closest(\'tr\'))">';
                            
                            // Create row
							trHtml += '<tr>';
                            ordered.forEach(function(c) {
                                if (!c.visible) return;
                                var val = items[c.key] !== undefined && items[c.key] !== null ? items[c.key] : '';
                                if (c.numeric && val !== '' && c.key !== 'tot_pcs') {
                                    val = money_format_india(parseFloat(val).toFixed(c.key.includes('wt') || c.key.includes('pct') ? 3 : 2));
                                }
                                var align = c.numeric ? 'style="text-align:right"' : 'style="text-align:left"';
                                trHtml += '<td ' + align + '>' + val + '</td>';
                            });
                            trHtml += '</tr>';
						});

                        // Accumulate Grand Totals
                        for (var k in section_totals) { grand_totals[k] += section_totals[k]; }

                        // Sub Total Row
						trHtml += '<tr style="color:blue">';
                        var firstSubCol = true;
                        ordered.forEach(function(c) {
                            if (!c.visible) return;
                            if (firstSubCol) {
                                trHtml += '<td style="text-align:left;"><strong>SUB TOTAL</strong></td>';
                                firstSubCol = false;
                            } else {
                                if (c.numeric && section_totals[c.key] !== undefined && c.key !== 'wastage_percent') {
                                    var tVal = section_totals[c.key];
                                    if (c.key === 'tot_pcs') tVal = parseFloat(tVal);
                                    else tVal = money_format_india(parseFloat(tVal).toFixed(c.key.includes('wt') ? 3 : 2));
                                    trHtml += '<td style="text-align:right;"><strong>' + tVal + '</strong></td>';
                                } else {
                                    trHtml += '<td></td>';
                                }
                            }
                        });
                        trHtml += '</tr>';
					});

                    // Grand Total Row
                    trHtml += '<tr style="color:blue">';
                    var firstGrandCol = true;
                    ordered.forEach(function(c) {
                        if (!c.visible) return;
                        if (firstGrandCol) {
                            trHtml += '<td style="text-align:left;"><strong>GRAND TOTAL</strong></td>';
                            firstGrandCol = false;
                        } else {
                            if (c.numeric && grand_totals[c.key] !== undefined && c.key !== 'wastage_percent') {
                                var gVal = grand_totals[c.key];
                                if (c.key === 'tot_pcs') gVal = parseFloat(gVal);
                                else gVal = money_format_india(parseFloat(gVal).toFixed(c.key.includes('wt') ? 3 : 2));
                                trHtml += '<td style="text-align:right;"><strong>' + gVal + '</strong></td>';
                            } else {
                                trHtml += '<td></td>';
                            }
                        }
                    });
                    trHtml += '</tr>';

					$('#itemwise-sales_detail > tbody').html(trHtml);

                    // columnDefs for alignment
                    var colDefs = [];
                    var visibleCols = ordered.filter(function(c){return c.visible;});
                    var rightIdxs = visibleCols.map(function(c,i){return c.numeric?i:null;}).filter(function(i){return i!==null;});
                    if (rightIdxs.length) colDefs.push({targets: rightIdxs, className:'dt-body-right'});

					$('#itemwise-sales_detail').dataTable({
							"bDestroy": true,
							"bSort": false,
							"bInfo": true,
							"scrollX": '100%',
							"dom": 'lBfrtip',
							"columnDefs": colDefs,
                            "colReorder": true,
							"lengthMenu": [[-1, 25, 50, 100, 250], ["All", 25, 50, 100, 250]],
							"buttons": [
								{
									extend: 'print',
									footer: true,
									title: '',
									messageTop: title,
									customize: function (win) {
										$(win.document.body).find('table')
											.addClass('compact')
											.css('font-size', '10px');
                                        $(win.document.body).find('table tbody tr').each(function () {
                                            const cellText = $(this).text().toLowerCase();
                                            if (cellText.includes('sub total') || cellText.includes('total') || cellText.includes('tag total')|| cellText.includes('non tag')||find('.prt_header')) {
                                                $(this).addClass('highlight-row');
                                            }
                                        });
                                        $(win.document.head).append(`
                                            <style>
                                            .highlight-row{ font-weight: bold !important; }
                                            tbody > tr > td { color: rgb(0, 0, 0) !important; }
                                            @media print{
                                                .highlight-row{ font-weight: bold !important; }
                                                tbody > tr > td { color: rgb(0, 0, 0) !important; }
                                            }
                                            </style>
                                        `);
									},
									exportOptions: {
										columns: ':visible',
										stripHtml: true
									}
								},
								{
									extend: 'colvis',
									collectionLayout: 'fixed columns',
									collectionTitle: 'Column visibility control'
								},
								{
									extend: 'excel',
									footer: true,
									title: 'Product Wise Sales Report',
								}
							],
						});
				}
			} else {
				if (list != null) {
                    // Destroy existing DataTable first
                    if ($.fn.DataTable.isDataTable('#sales_summary_report')) {
                        $('#sales_summary_report').DataTable().destroy();
                    }
                    $('#sales_summary_report > tbody').empty();

                    // Resolve ordered columns from activeSummaryCfg
                    var sumOrdered = activeSummaryCfg.map(function(c) {
                        var def = SUMMARY_COL_MAP.find(function(d){ return d.key === c.key; });
                        return def ? Object.assign({}, def, {visible: c.visible}) : null;
                    }).filter(Boolean);

                    // Rebuild <thead> with only visible columns
                    var sumVisible = sumOrdered.filter(function(c){ return c.visible; });
                    $('#sales_summary_report > thead').html(
                        '<tr>' + sumVisible.map(function(c){ return '<th>' + c.label + '</th>'; }).join('') + '</tr>'
                    );

                    // Grand total accumulators (raw numbers)
                    var sumGrand = {};
                    sumOrdered.forEach(function(c){ sumGrand[c.key] = 0; });

                    var trHtml = '';
                    $.each(list, function (key, val) {
                        // Compute derived fields
                        var rowDiff    = parseFloat(val.tag_gross_wt) - parseFloat(val.gross_wt);
                        var rowWastPct = parseFloat(val.wastage_percent) /
                                         (parseFloat(val.tagcount) > 0 ? parseFloat(val.tagcount) : parseFloat(val.tot_pcs));

                        // Raw value map keyed by SUMMARY_COL_MAP keys
                        var rowRaw = {
                            section_name:    val.section_name,
                            purity:          val.purity,
                            tagcount:        parseFloat(val.tagcount) || 0,
                            tot_pcs:         parseFloat(val.tot_pcs)  || 0,
                            gross_wt:        parseFloat(val.gross_wt) || 0,
                            diawt:           parseFloat(val.diawt)    || 0,
                            dia_amt:         parseFloat(val.dia_amt)  || 0,
                            net_wt:          parseFloat(val.net_wt)   || 0,
                            tag_gross_wt:    parseFloat(val.tag_gross_wt) || 0,
                            diff_wt:         rowDiff,
                            wastage_percent: rowWastPct,
                            wast_wt:         parseFloat(val.wast_wt)  || 0,
                            mc_value:        parseFloat(val.mc_value) || 0,
                            total_cost:      parseFloat(val.total_cost) || 0,
                            stn_amt:         parseFloat(val.stn_amt)  || 0,
                        };

                        // Accumulate grand totals (skip derived wastage_percent)
                        sumOrdered.forEach(function(c) {
                            if (c.numeric && c.key !== 'wastage_percent') {
                                sumGrand[c.key] += rowRaw[c.key] || 0;
                            }
                        });

                        // Build data row
                        trHtml += '<tr>';
                        sumOrdered.forEach(function(c) {
                            if (!c.visible) return;
                            var v = (rowRaw[c.key] !== undefined) ? rowRaw[c.key] : '';
                            if (c.numeric && v !== '') {
                                if (c.key === 'tagcount') { v = Math.round(v); }
                                else if (c.key === 'tot_pcs') { v = Math.round(v); }
                                else if (c.key === 'wastage_percent') { v = parseFloat(v).toFixed(2); }
                                else if (c.key.indexOf('wt') !== -1) { v = money_format_india(parseFloat(v).toFixed(3)); }
                                else { v = money_format_india(parseFloat(v).toFixed(2)); }
                            }
                            var align = c.numeric ? 'style="text-align:right"' : 'style="text-align:left"';
                            trHtml += '<td ' + align + '>' + v + '</td>';
                        });
                        trHtml += '</tr>';
                    });

                    // Grand Total Row
                    trHtml += '<tr style="font-weight:bold;color:blue;">';
                    var firstGrand = true;
                    sumOrdered.forEach(function(c) {
                        if (!c.visible) return;
                        if (firstGrand) {
                            trHtml += '<td style="text-align:left;"><strong>GRAND TOTAL</strong></td>';
                            firstGrand = false;
                        } else if (c.numeric && c.key !== 'wastage_percent') {
                            var gv = sumGrand[c.key] || 0;
                            var gs;
                            if (c.key === 'tagcount') { gs = Math.round(gv); }
                            else if (c.key.indexOf('wt') !== -1 || c.key === 'tot_pcs') { gs = money_format_india(parseFloat(gv).toFixed(3)); }
                            else { gs = money_format_india(parseFloat(gv).toFixed(3)); }
                            trHtml += '<td style="text-align:right;"><strong>' + gs + '</strong></td>';
                        } else {
                            trHtml += '<td></td>';
                        }
                    });
                    trHtml += '</tr>';

                    $('#sales_summary_report > tbody').html(trHtml);

                    // Dynamic columnDefs: align right for numeric, left for text
                    var sumColDefs = [];
                    var sumRightIdxs = sumVisible.map(function(c, i){ return c.numeric ? i : null; }).filter(function(i){ return i !== null; });
                    var sumLeftIdxs  = sumVisible.map(function(c, i){ return !c.numeric ? i : null; }).filter(function(i){ return i !== null; });
                    if (sumRightIdxs.length) sumColDefs.push({targets: sumRightIdxs, className: 'dt-body-right'});
                    if (sumLeftIdxs.length)  sumColDefs.push({targets: sumLeftIdxs,  className: 'dt-body-left'});

					$('#sales_summary_report').dataTable({
							"bDestroy": true,
							"bSort": false,
							"bInfo": true,
							"scrollX": '100%',
							"dom": 'lBfrtip',
							"columnDefs": sumColDefs,
							"lengthMenu": [[-1, 25, 50, 100, 250], ["All", 25, 50, 100, 250]],
							"buttons": [
								{
									extend: 'print',
									footer: true,
									title: '',
									messageTop: title,
									customize: function (win) {
										$(win.document.body).find('table')
											.addClass('compact')
											.css('font-size', '10px');
									},
									exportOptions: {
										columns: ':visible',
										stripHtml: true
									}
								},
								{
									extend: 'colvis',
									collectionLayout: 'fixed columns',
									collectionTitle: 'Column visibility control'
								},
								{
									extend: 'excel',
									footer: true,
									title: 'Product Wise Sales Report (Summary)',
								}
							],
						});
				}
			}

		},
		error: function (error) {
			$("div.overlay").css("display", "none");
		}
	});
}
//device wise collection
$('#device_pay_search').click(function (event) {
	set_devicepayBills();
});
function get_ActiveDevicename() {
	$('#device_name option').remove();
	$.ajax({
		url: base_url + 'index.php/admin_ret_reports/get_ActiveDevicename',
		dataType: "JSON",
		type: "POST",
		success: function (data) {
			var id = $("#id_pay_device").val();
			$("#device_name").append(
				$("<option></option>")
					.attr("value", 0)
					.text('All')
			);
			$.each(data, function (key, item) {
				$("#device_name").append(
					$("<option></option>")
						.attr("value", item.id_device)
						.text(item.device_name)
				);
			});
			$("#device_name").select2(
				{
					placeholder: "Select Device Name",
					allowClear: true
				});
			$("#device_name").select2("val", (id != '' && id > 0 ? id : ''));
			if ($("#device_name").length) {
				$("#device_name").select2("val", (id != '' && id > 0 ? id : ''));
			}
		}
	});
}
function set_devicepayBills() {
	var dt_range = ($("#dt_range").val()).split('-');
	var company_name = $('#company_name').val();
	var from_date = dt_range[0];
	var to_date = dt_range[1];
	var branch_name = ($('#branch_name').val() != '' && $('#branch_name').val() != undefined ? $('#branch_name').val() : $("#branch_select option:selected").text());
	var report_name = "Pay Device Report"
	var optional = $('#device_name option:selected').html() != '' && $('#device_name option:selected').html() != undefined ? $('#device_name option:selected').html() + ' - ' : '';
	var title = "<div style='text-align: center;'><b><span style='font-size:15pt;'>" + company_name + "</span></b><b><span style='font-size:12pt;'></span></b></br>"
		+ "<span>" + report_print(branch_name, report_name, from_date, to_date, optional) + "</span>";
	$("div.overlay").css("display", "block");
	my_Date = new Date();
	$.ajax({
		url: base_url + "index.php/admin_ret_reports/pay_device/ajax?noncache=" + my_Date.getUTCSeconds(),
		data: ({ 'dt_range': $("#dt_range").val(),
			 'id_branch': ($('#branch_filter').val() != '' && $('#branch_filter').val() != undefined ? $('#branch_filter').val() : $("#branch_select").val()),
			  'id_pay_device': $("#device_name").val(),
			  'type_filter': $("#source_filter").val() // ✅ NEW FILTER
			 }),
		dataType: "JSON",
		type: "POST",
		success: function (data) {
			$("div.overlay").css("display", "none");
			var list = data.list;
			var oTable = $('#pay_device_list').DataTable();
			oTable.clear().draw();
			if (list != null && list.length > 0) {
				$('#total_count').text(list.length);
				oTable = $('#pay_device_list').dataTable({
					"bDestroy": true,
					"bInfo": true,
					"bFilter": true,
					"order": [[0, "desc"]],
					"scrollX": '100%',
					"bSort": true,
					"dom": 'lBfrtip',
					"columnDefs": [
						{
							targets: [10],
							className: 'dt-body-right'
						},
					],
					"buttons": [
						{
							extend: 'print',
							footer: true,
							title: '',
							messageTop: title,
							customize: function (win) {
								$(win.document.body).find('table')
									.addClass('compact')
									.css('font-size', '10px');
							},
						},
						{
							extend: 'colvis',
							collectionLayout: 'fixed columns',
							collectionTitle: 'Column visibility control'
						},
						{
							extend: 'excel',
							footer: true,
							title: function () {
									return (
										$('#company_name').val() + " - " +
										"Pay Device Report  " +" - "+
										($("#branch_select option:selected").text() != 'All' ?  $("#branch_select option:selected").text() : '' ) +" - "+ "FROM : " + $("#dt_range").val().replace('-', ' TO ') + " - " +
										($('.hidden-xs').html() || ' Developer') + " - " + getDisplayDateTime()
										);
								},
						}
					],
					"aaData": list,
					"aoColumns": [
						{ "mDataProp": "branch" },
						{ "mDataProp": "bill_date" },
						{ "mDataProp": "bill_time" },
						{
							"mDataProp": function (row, type, val, meta) {
								var url = base_url + 'index.php/admin_ret_billing/billing_invoice/' + row.bill_id;
								return '<a href=' + url + ' target="_blank">' + row.bill_no + '</a>';
							}
						},
						{ "mDataProp": "cus_name" },
						{ "mDataProp": "mobile" },
						{ "mDataProp": "report_type" },
						{ "mDataProp": "device_name" },
						{ "mDataProp": "card_type" },
						{ "mDataProp": "card_no" },
						{ "mDataProp": "approvalno" },
						
						{
							"mDataProp": function (row, type, val, meta) {
								var amount = parseFloat(row.amount);
								var formatted = money_format_india(Math.abs(amount).toFixed(2));
								return (amount < 0 ? '-' : '') + formatted;
							}
						},
					],
					"footerCallback": function (row, data, start, end, display) {
						if (data.length > 0) {
							var api = this.api(), data;
							for (var i = 0; i <= data.length - 1; i++) {
								var intVal = function (i) {
									return typeof i === 'string' ?
										parseFloat(i.replace(/,/g, '')) || 0 :
										typeof i === 'number' ?
											i : 0;
								};
								$(api.column(0).footer()).html('Total');
								amount = api
									.column(11)
									.data()
									.reduce(function (a, b) {
										return intVal(a) + intVal(b);
									}, 0);
								var formatted = money_format_india(Math.abs(amount).toFixed(2));
								$(api.column(11).footer()).html((amount < 0 ? '-' : '') + formatted);
							}
						} else {
							var api = this.api(), data;
							$(api.column(11).footer()).html('');
						}
					}
				});
			}
		},
		error: function (error) {
			$("div.overlay").css("display", "none");
		}
	});
}
