		total_net_net_wt = parseFloat(parseFloat(total_sales_net_wt) - parseFloat(total_ret_sales_net_wt));
		total_net_taxable_amt = parseFloat(parseFloat(total_sales_taxable_amt) - parseFloat(total_ret_sales_taxable_amt));
