/*select transfer report*/
function get_po_ref_nos() {
	$(".overlay").css('display', 'block');
	$.ajax({
		type: 'GET',
		url: base_url + 'index.php/admin_ret_reports/get_po_ref_nos',
		dataType: 'json',
		success: function (data) {
			var po_id = $('#select_po_ref_no').val();
			$.each(data, function (key, item) {
				$('#select_po_ref_no').append(
					$("<option></option>")
						.attr("value", item.po_id)
						.text(item.po_ref_no)
				);
			});
			$("#select_po_ref_no").select2({
				placeholder: "Select PO Ref No",
				allowClear: true
			});
			$("#select_po_ref_no").select2("val", (po_id != '' && po_id > 0 ? po_id : ''));
			$(".overlay").css("display", "none");
		}
	});
}
//Stock Issue Receipt Report
if (typeof ctrl_page !== 'undefined' && ctrl_page[1] == 'stock_issue_report') {
	$(document).ready(function() {
		$("#search_by, #status_type, #item_type, #report_type, #GroupBy").select2({
			minimumResultsForSearch: -1, // optional: hide search box for small dropdowns, or remove this line to allow search
            width: '100%'
		});
	});
}
$('#report_type').on('change', function (e) {
	if (ctrl_page[1] == 'stock_issue_report') {
		if (this.value == 2) {
			$('.GroupBy').css("display", "block");
			$('.Cat_StockIssue').css("display", "block");
			$('.StockIssue').css("display", "none");
			$('.det').css("display", "none");
			$('#karigar').val(0);
			$('#status_type').val(0);
			if (typeof get_ActiveKarigars === 'function') {
				get_ActiveKarigars();
			}
		}
		else {
			$('.det').css("display", "block");
			$('.GroupBy').css("display", "none");
			$('.Cat_StockIssue').css("display", "none");
			$('.StockIssue').css("display", "block");
		}
		get_stock_issue_report();
	}
});
$('#GroupBy').on('change', function (e) {
	if (this.value == 1) {
		$('.Cat_StockIssue').css("display", "block");
		$('.StockIssue').css("display", "none");
	}
	else {
		$('.Cat_StockIssue').css("display", "none");
		$('.StockIssue').css("display", "block");
	}
	get_stock_issue_report();
});
$('#search_by').on('change', function (e) {
	if (this.value != '') {
		get_stock_issue_report();
	}
});
$('#stock_issue_search').click(function (event) {
	get_stock_issue_report();
});
function get_stock_issue_report() {
	$("div.overlay").css("display", "block");
	var report_type = $('#report_type').val();
	var GroupBy = $('#GroupBy').val();
	var dt_range = ($("#dt_range").val()).split('-');
	var company_name = $('#company_name').val();
	var company_code = $('#company_code').val();
	var branch_name = ($('#branch_name').val() != '' && $('#branch_name').val() != undefined ? $('#branch_name').val() : $('#branch_select option:selected').toArray().map(item => item.text).join());
	var company_code = $('#company_code').val();
	var company_address1 = $('#company_address1').val();
	var company_address2 = $('#company_address2').val();
	var company_city = $('#company_city').val();
	var pincode = $('#pincode').val();
	var company_email = $('#company_email').val();
	var company_gst_number = $('#company_gst_number').val();
	var phone = $('#phone').val();
	var title = "<div style='text-align: center;'><b><span style='font-size:12pt;'>" + company_code + "</span></b></br>"
		+ "<span style='font-size:11pt;'>" + company_address1 + "</span></br>"
		+ "<span style='font-size:11pt;'>" + company_address2 + company_city + "-" + pincode + "</span></br>"
		+ "<span style='font-size:11pt;'>GSTIN:" + company_gst_number + ", EMAIL:" + company_email + "</span></br>"
		+ "<span style='font-size:11pt;'>Contact :" + phone + "</span></br>"
		+ "<span style=font-size:12pt;>Stock Issue Report - " + branch_name + " &nbsp;&nbsp; From: " + dt_range[0] + " To:" + dt_range[1] + " - " + $('.hidden-xs').html() + "</span>";
	my_Date = new Date();
	$.ajax({
		url: base_url + "index.php/admin_ret_reports/stock_issue_report/ajax?nocache=" + my_Date.getUTCSeconds(),
		data: ({ 'dt_range': $("#dt_range").val(), 'id_branch': ($('#branch_filter').val() != '' && $('#branch_filter').val() != undefined ? $('#branch_filter').val() : $("#branch_select").val()), 'issue_type': $('#issue_type').val(), 'id_karigar': $("#karigar").val(), 'search_by': $('#search_by').val(), 'report_type': $('#report_type').val(), 'GroupBy': $('#GroupBy').val(), 'status_type': $('#status_type').val(), 'item_type': $('#item_type').val() }),
		dataType: "JSON",
		type: "POST",
		success: function (data) {
			$("div.overlay").css("display", "none");
			var list = data.list;
			print_stock_issue = list;
			console.log(data);
			if (report_type == 1 || (report_type == 2 && GroupBy == 2)) {
				if ($.fn.DataTable.isDataTable('#stock_issue_list')) {
					$('#stock_issue_list').DataTable().clear().draw();
				}
				if (list != null && list.length > 0) {
					oTable = $('#stock_issue_list').dataTable({
						"bDestroy": true,
						"bInfo": true,
						"bFilter": true,
						"order": [[0, "asc"]],
						"lengthMenu": [[-1, 25, 50, 100, 250], ["All", 25, 50, 100, 250]],
						"scrollX": '100%',
						"bSort": true,
						"dom": 'lBfrtip',
						"columnDefs": [
							{
								targets: [5, 6],
								className: 'dt-body-right'
							},
						],
						"buttons": [
							{
								extend: 'print',
								footer: true,
								stripHtml: false,
								title: "",
								messageTop: title,
								customize: function (win) {
									$(win.document.body).find('table')
										.addClass('compact')
										.css('font-size', 'inherit');
								},
							},
							{
								extend: 'colvis',
								collectionLayout: 'fixed columns',
								collectionTitle: 'Column visibility control'
							},
							{
								extend: 'excel',
								footer: true,
								title: 'Stock Issue Report' + branch_name + '-' + dt_range[0] + '-' + dt_range[1],
							}
						],
						"aaData": list,
						"aoColumns": [
							{ "mDataProp": "issue_no" },
							{ "mDataProp": "issue_type" },
							{ "mDataProp": "issue_date" },
							{ "mDataProp": "received_date" },
							{ "mDataProp": "tag_code" },
							{ "mDataProp": "product_name" },
							{
								"mDataProp": function (row, type, val, meta) {
									return money_format_india(row.tag_pcs);
								}
							},
							{
								"mDataProp": function (row, type, val, meta) {
									return money_format_india(row.tag_weight);
								}
							},
							{ "mDataProp": "name" },
							{ "mDataProp": "branch" },
							{ "mDataProp": "issue_status" }
						],
						"footerCallback": function (row, data, start, end, display) {
							var api = this.api(), data;
							// Remove the formatting to get integer data for summation
							var intVal = function (i) {
								return typeof i === 'string' ?
									i.replace(/[\$,]/g, '') * 1 :
									typeof i === 'number' ?
										i : 0;
							};
							total_pcs = api
								.column(6)
								.data()
								.reduce(function (a, b) {
									return intVal(a) + intVal(b);
								}, 0);
							total_weight = api
								.column(7)
								.data()
								.reduce(function (a, b) {
									return intVal(a) + intVal(b);
								}, 0);
							// Total over all pages
							// Update footer
							$(api.column(6).footer()).html(money_format_india(parseFloat(total_pcs).toFixed(0)));
							$(api.column(7).footer()).html(money_format_india(parseFloat(total_weight).toFixed(3)));
						}
					});
				}
			}
			else {
				// Destroy existing DataTable instance cleanly before reinit
				if ($.fn.DataTable.isDataTable('#cat_stock_issue_list')) {
					$('#cat_stock_issue_list').DataTable().destroy();
				}
				if (list != null && list.length > 0) {
					oTable = $('#cat_stock_issue_list').dataTable({
						"bInfo": true,
						"bFilter": true,
						"order": [[0, "asc"]],
						"lengthMenu": [[-1, 25, 50, 100, 250], ["All", 25, 50, 100, 250]],
						"bSort": true,
						"dom": 'lBfrtip',
						"columnDefs": [
							{
								targets: [3, 4],
								className: 'dt-body-right'
							},
						],
						"buttons": [
							{
								extend: 'print',
								footer: true,
								stripHtml: false,
								title: "",
								messageTop: title,
								customize: function (win) {
									$(win.document.body).find('table')
										.addClass('compact')
										.css('font-size', 'inherit');
								},
							},
							{
								extend: 'excel',
								footer: true,
								title: 'Stock Issue Report' + branch_name + '-' + dt_range[0] + '-' + dt_range[1],
							}
						],
						"aaData": list,
						"aoColumns": [
							{ "mDataProp": "category" },
							{ "mDataProp": "issue_type" },
							{
								"mDataProp": function (row, type, val, meta) {
									if ($('#search_by').val() == 2) {
										return row.received_date || '';
									}
									return row.issue_date || '';
								},
							},
							{
								"mDataProp": function (row, type, val, meta) {
									return money_format_india(row.tag_pcs);
								}
							},
							{
								"mDataProp": function (row, type, val, meta) {
									return money_format_india(row.tag_weight);
								}
							},
							{ "mDataProp": "branch" },
							{ "mDataProp": "issue_status" }
						],
						"footerCallback": function (row, data, start, end, display) {
							var api = this.api();
							var intVal = function (i) {
								return typeof i === 'string' ?
									i.replace(/[\$,]/g, '') * 1 :
									typeof i === 'number' ?
										i : 0;
							};
							var total_pcs = api.column(3).data().reduce(function (a, b) {
								return intVal(a) + intVal(b);
							}, 0);
							var total_wt = api.column(4).data().reduce(function (a, b) {
								return intVal(a) + intVal(b);
							}, 0);
							$(api.column(3).footer()).html(money_format_india(parseFloat(total_pcs).toFixed(0)));
							$(api.column(4).footer()).html(money_format_india(parseFloat(total_wt).toFixed(3)));
						}
					});
					// Adjust columns in case container had layout issues
					oTable.api().columns.adjust();
				}
			}
			$("div.overlay").css("display", "none");
		},
		error: function (error) {
			$("div.overlay").css("display", "none");
		}
	});
}
