$('#duplicate_print').on('click', function () {
	var tag_id = $("#tag_id").val();
	if (tag_id != "") {
		duplicate_tagging_print(tag_id);
	}
	else {
		$.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>" + 'Please Enter the Tag Number.' });
		$("div.overlay").css("display", "none");
	}
});
