function get_hsncode() {
	$("#hsn_code option").remove();
	$.ajax({
		type: 'POST',
		url: base_url + 'index.php/admin_ret_catalog/category/hsn_code',
		dataType: 'json',
		data: { 'id_metal': $('#metal').val() },
		success: function (data) {
			var catItems = data.categorymtr;
			$("#hsn_code").append(
				$("<option></option>")
					.attr("value", 0)
					.text('All')
			);
			$.each(catItems, function (key, item) {
				if (item.hsn_code != '' && item.hsn_code != null) {
					$('#hsn_code').append(
						$("<option></option>")
							.attr("value", item.hsn_code)
							.text(item.hsn_code)
					);
				}
			});
			$('#hsn_code').select2({
				placeholder: "HSN Code",
				allowClear: true
			});
		}
	});
	$("div.overlay").css("display", "none");
}
