function get_Active_purity() {
	$('#select_purity option').remove();
	$(".overlay").css('display', 'block');
	$.ajax({
		type: 'POST',
		url: base_url + 'index.php/admin_ret_catalog/category/cat_purity',
		dataType: 'json',
		data: { 'id_category': $('#category').val() },
		success: function (data) {
			var id_purity = $('#id_purity').val();
			// The endpoint returns one row per category+purity mapping, so the same
			// purity comes back once per category it is mapped to (75.0000 x60, etc).
			// Collapse to one option per distinct purity VALUE — the master also holds
			// several ids for the same value (91.6000 = ids 1,18,23,33), so the option
			// carries every matching id and the report filters with "purity IN (...)".
			var byValue = {};
			var order = [];
			$.each(data, function (key, item) {
				if (item.id_purity == null || item.purity == null || item.purity === '') return;
				if (!byValue[item.purity]) { byValue[item.purity] = []; order.push(item.purity); }
				if ($.inArray(item.id_purity, byValue[item.purity]) === -1) {
					byValue[item.purity].push(item.id_purity);
				}
			});
			order.sort(function (a, b) { return parseFloat(a) - parseFloat(b); });
			$.each(order, function (i, purity) {
				$('#select_purity').append(
					$("<option></option>")
						.attr("value", byValue[purity].join(','))
						.text(purity)
				);
			});
			$("#select_purity").select2({
				placeholder: "Select Purity",
				allowClear: true
			});
			if ($("#select_purity").length) {
				// A stored id_purity is a single id, but option values are now id lists —
				// resolve it to the option that contains it.
				var preset = '';
				if (id_purity != '' && id_purity > 0) {
					$('#select_purity option').each(function () {
						if ($.inArray(String(id_purity), String(this.value).split(',')) !== -1) {
							preset = this.value;
							return false;
						}
					});
				}
				$("#select_purity").select2("val", preset);
			}
			$(".overlay").css("display", "none");
		}
	});
}
