							sub_tot_sales_upi_transf += parseFloat(upi_transfer_payment);

							sub_tot_sales_rtgs += parseFloat(rtgs_payment);

							sub_tot_sales_imps += parseFloat(imps_payment);

							sub_tot_sales_neft += parseFloat(neft_payment);

