$(document).ready(function() {
    function toggleHuidField() {
        if ($('#tagged').prop('checked')) {
            $('.huid_block').show();  // Show the HUID field
        } else {
            $('.huid_block').hide();  // Hide the HUID field
        }
    }
    // Run the toggle function initially
    toggleHuidField();
    // Add event listeners to the radio buttons
    $('#tagged, #non_tagged').change(function() {
        toggleHuidField();
    });
});
$('#get_print_log').on('click', function () {
	$('#duplicate_print_log > tbody').empty();
	let startDate = $('#print_date1').html();
	let endDate = $('#print_date2').html();
	if ($('#id_branch').val() == '') {
		$.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>" + 'Please Select The Branch..' });
		return false;
	}
	else if ($('#id_product').val() == '' && ($('#tag_no').val() == '' && $('#old_tag_no').val() == '')) {
		$.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>" + 'Product or Tag code Is Required..' });
		return false;
	}
	else {
		$("div.overlay").css("display", "block");
		var branch_name=$('#branch_select').val();
		var my_Date = new Date();
		var fromdate=$('#print_date1').val();
		var todate=$('#print_date2').val();
		report_name = "Duplicate taging";
		var title = "<div style='text-align: center;'><b><span style='font-size:15pt;'>" + company_name + "</span></b><b><span style='font-size:12pt;'></span></b></br>"
		+ "<span>" + report_print(branch_name, report_name, fromdate, todate) + "</span>";
		$.ajax({
			url: base_url + 'index.php/admin_ret_reports/duplicate_tag_print_log/ajax?nocache=' + my_Date.getUTCSeconds(),
			dataType: "json",
			type: "POST",
			data: { 
				'id_branch'			: $('#id_branch').val(), 
				'tag_id'			: $('#tag_id').val(), 
				'id_product'		: $('#prod_select').val(), 
				'des_select'		: $('#des_select').val(), 
				'sub_des_select'	: $('#sub_des_select').val(), 
				'tag_code'			: $('#tag_no').val(), 
				'old_tag_code'		: $('#old_tag_no').val(),
				'startDate'			: fromdate,
				'endDate'			: todate,
			},
			success: function (data) {

				$('#tag_no').val('');

				duplicate_tag_print_log = [];

				$.each(data, function (key, item) {

					duplicate_tag_print_log.push({
						'print_id': item.print_id,
						'branch_name': item.branch_name,
						'tag_id': item.tag_id,
						'old_tag_id': item.old_tag_id,
						'tag_code': item.tag_code,
						'product_name': item.product_name,
						'design_name': item.design_name,
						'sub_design_name': item.sub_design_name,
						'printer': item.printer_name,
						'employee': item.print_taken_by,
						'date': item.printed_on
					});
				});
				set_duplicate_tag_print_log();
				
			}
			
		});
		
	}
});

function set_duplicate_tag_print_log() {
	if ($.fn.DataTable.isDataTable('#duplicate_print_log')) {
		$('#duplicate_print_log').DataTable().destroy();
	}
	$('#duplicate_print_log > tbody').empty();
	$("div.overlay").css("display", "block");
	var row = '';
	var company_name = $('#company_name').val();
	var branch_name = $("#branch_select option:selected").text();

		var my_Date = new Date();
		var fromdate=$('#print_date1').html();
		var todate=$('#print_date2').html();
		var report_name = "Duplicate taging";
		var title = "<div style='text-align: center;'><b><span style='font-size:15pt;'>" + company_name + "</span></b><b><span style='font-size:12pt;'></span></b></br>"
		+ "<span>" + report_print(branch_name, report_name, fromdate, todate,'') + "</span></div>";
	$.each(duplicate_tag_print_log, function (key, item) {

		var rowExist = false;

		$('#duplicate_print_log > tbody tr').each(function (bidx, trow) {

			curRow = $(this);

			if (curRow.find('#print_id').val() != '') {

				if (item.print_id == curRow.find('#print_id').val()) {

					rowExist = true;

				}

			}

		});

		if (!rowExist) {
		
			row = '<tr id="' + key + '">'

				+ '<td style="text-align: left;"><span>' + item.branch_name + '<input type="hidden" id="print_id" value="' + item.print_id + '"></td>'

				+ '<td style="text-align: left;"><input type="hidden" class="tag_id" name="tag_id[]" value="' + item.tag_id + '"><input type="hidden" class="tag_code" name="tag_code[]" value="' + item.tag_code + '">' + item.tag_code + '</td>'

				+ '<td style="text-align: left;"><input type="hidden" class="old_tag_id" name="old_tag_code[]" value="' + item.old_tag_id + '">' + (item.old_tag_id ? '<input type="hidden" class="old_tag_code" name="old_tag_code[]" value="' + item.old_tag_id + '">' + item.old_tag_id : '') + '</td>'

				+ '<td style="text-align: left;">' + item.product_name + '</td>'

				+ '<td style="text-align: left;">' + item.design_name + '</td>'

				+ '<td style="text-align: left;">' + item.sub_design_name + '</td>'

				+ '<td style="text-align: left;">' + item.employee + '</td>'

				+ '<td style="text-align: left;">' + item.date + '</td>'

				// + '<td style="text-align: left;">' + item.printer + '</td>'

				+ '</tr>';

			$('#duplicate_print_log > tbody').append(row);

			// $('#duplicate_print_log  > tbody ').html(trHTML);
		
		}
		
	});
	// $('#duplicate_print_log  > tbody ').html(row);

		oTable = $('#duplicate_print_log').dataTable({
			"bSort": false,
			"bDestroy": true,
			"bInfo": true,
			"scrollX": '100%',
			"paging": false,
			"dom": 'Bfrtip',
			"bAutoWidth": false,
			"responsive": true,
			"buttons": [
				{
					extend: 'print',
					footer: true,
					title: '',
					messageTop: title,
					customize: function (win) {
						$(win.document.body).find('table')
							.addClass('compact')
							.css('font-size', '10px');
					},
				},
				{
					extend: 'excel',
					footer: true,
					title: 'Rate Fixed Report',
				}
			],
		});
	$("div.overlay").css("display", "none");
}
$('#tag_huid').on('keyup', function () {
    let value = $(this).val().replace(/[^a-zA-Z0-9]/g, '');
    value = value.toUpperCase();
    $(this).val(value); 
    if (value.length > 6) {
        // If more than 6 characters, trim it to 6
        $(this).val(value.substring(0, 6));
		
    }
});
function get_daterange(){
	var date = new Date();
			var firstDay = new Date(date.getFullYear(), date.getMonth(), date.getDate() - 0, 1);
			var from_date = (firstDay.getDate() + "-" + (firstDay.getMonth() + 1) + "-" + firstDay.getFullYear());
			var to_date = (date.getDate() + "-" + (date.getMonth() + 1) + "-" + date.getFullYear());
			$('#rpt_from_date').html(from_date);
			$('#rpt_to_date').html(to_date);
			$('#rpt_date_picker').daterangepicker(
				{
					ranges: {
						'Today': [moment(), moment()],
						'Yesterday': [moment().subtract(1, 'days'), moment().subtract(1, 'days')],
						'Last 7 Days': [moment().subtract(6, 'days'), moment()],
						'Last 30 Days': [moment().subtract(29, 'days'), moment()],
						'This Month': [moment().startOf('month'), moment().endOf('month')],
						'Last Month': [moment().subtract(1, 'month').startOf('month'), moment().subtract(1, 'month').endOf('month')]
					},
					startDate: moment().subtract(0, 'days'),
					endDate: moment()
				},
				function (start, end) {
					// $('#reportrange').html(start.format('D/M/YYYY') + ' - ' + end.format('D/M/YYYY'));
					$('#rpt_date_picker').html(start.format('D/M/YYYY') + ' - ' + end.format('D/M/YYYY'));
					$('#rpt_from_date').html(start.format('DD-MM-YYYY'));
					$('#rpt_to_date').html(end.format('DD-MM-YYYY'));
				}
			);
}
