// Keep copies of petty cash options
var pettyCashPayment = $('#bill_type option[value="10"]').detach();
var pettyCashReceipt = $('#bill_type option[value="11"]').detach();

$('#det_sales_report_type').on('change', function () {
    var reportType = $(this).val();

    if (reportType == "3") {
        // Add them back
        if ($('#bill_type option[value="10"]').length === 0) {
            $('#bill_type').append(pettyCashPayment);
        }
        if ($('#bill_type option[value="11"]').length === 0) {
            $('#bill_type').append(pettyCashReceipt);
        }
    } else {
        // If currently selected, reset to All
        if ($('#bill_type').val() === "10" || $('#bill_type').val() === "11") {
            $('#bill_type').val("0");
        }
        // Remove the options
        $('#bill_type option[value="10"]').detach();
        $('#bill_type option[value="11"]').detach();
    }
});
