// Delegate click on report rows
$(document).on('click', '.emp_pcs_log_cell', function() {
	var product_id = $(this).data('product');
	var id_section = $(this).data('section');
	var id_branch  = $(this).data('branch');
	var date_raw   = $(this).data('date'); // e.g. "15-04-2026-15-04-2026" or single date
	var product_name = $(this).data('name');

	// Extract first date from range
	var date_parts = String(date_raw).split(' - ');
	var date = date_parts[0] ? date_parts[0].trim() : date_raw;

	$('#entry_log_product_info').text('Product: ' + product_name);
	$('#entry_log_tbody').html('<tr><td colspan="6" class="text-center"><i class="fa fa-spinner fa-spin"></i> Loading...</td></tr>');
	$('#entry_log_modal').modal('show');

	load_employee_entry_log(product_id, id_section, id_branch, date);
});

// Delegate click on list page pcs column (for employee_product_stock_list table)
$(document).on('click', '#employee_product_stock_list tbody td.emp_log_pcs', function() {
	var tr = $(this).closest('tr');
	var date = tr.find('.log_date').text().trim();
	var id_branch = $('#log_id_branch').val();
	var product_id = tr.find('.log_product_id').val();
	var id_section = tr.find('.log_section_id').val();
	var product_name = tr.find('.log_product_name').text().trim();

	$('#entry_log_product_info').text('Product: ' + product_name);
	$('#entry_log_tbody').html('<tr><td colspan="6" class="text-center"><i class="fa fa-spinner fa-spin"></i> Loading...</td></tr>');
	$('#entry_log_modal').modal('show');

	load_employee_entry_log(product_id, id_section, id_branch, date);
});

function load_employee_entry_log(product_id, id_section, id_branch, date) {
	var my_Date = new Date();
	$.ajax({
		url: base_url + 'index.php/admin_ret_catalog/employee_stock_product/get_entry_log?nocache=' + my_Date.getUTCSeconds(),
		type: 'POST',
		dataType: 'json',
		data: {
			product_id: product_id,
			id_section: id_section,
			id_branch:  id_branch,
			date:       date
		},
		success: function(data) {
			var html = '';
			if (data.length == 0) {
				html = '<tr><td colspan="6" class="text-center text-muted">No entries found for this product on selected date.</td></tr>';
			} else {
				$.each(data, function(idx, row) {
					var typeLabel = (row.product_type == 2) ? '<span class="label label-warning">Non-Tagged</span>' : '<span class="label label-info">Tagged</span>';
					var qty = (row.product_type == 2)
						? (parseFloat(row.weight) > 0 ? parseFloat(row.weight).toFixed(3) + ' g' : '-')
						: (parseInt(row.pcs) > 0 ? row.pcs + ' pcs' : '-');
					html += '<tr>'
						+ '<td>' + (idx + 1) + '</td>'
						+ '<td>' + (row.employee_name || '-') + '</td>'
						+ '<td>' + (row.branch_name || '-') + '</td>'
						+ '<td><strong>' + qty + '</strong></td>'
						+ '<td>' + typeLabel + '</td>'
						+ '<td>' + (row.created_on || '-') + '</td>'
						+ '</tr>';
				});
			}
			$('#entry_log_tbody').html(html);
		},
		error: function() {
			$('#entry_log_tbody').html('<tr><td colspan="6" class="text-center text-danger">Error loading data.</td></tr>');
		}
	});
}

