// ==================== Physical Stock Inspect Report ====================

$(document).ready(function() {
	// Init inspect page datepickers
	if ($('#inspect_search_btn').length > 0) {
		$('#inspect_date_range').daterangepicker({
			format: 'DD/MM/YYYY',
			separator: ' - ',
			startDate: moment().startOf('month'),
			endDate: moment()
		});
	}
});

// Search handler for inspect page
$(document).on('click', '#inspect_search_btn', function () {
	get_stock_inspect_data();
});

function get_stock_inspect_data() {
	$("div.overlay").css("display", "block");

	var id_branch = ($('#inspect_branch_filter').val() != '' && $('#inspect_branch_filter').val() != undefined)
		? [$('#inspect_branch_filter').val()]
		: ($('#inspect_branch_select').val() || ['']);

	// Parse daterangepicker value "DD/MM/YYYY - DD/MM/YYYY"
	var rangeVal = $('#inspect_date_range').val() || '';
	var rangeParts = rangeVal.split(' - ');
	var fromDate = rangeParts[0] || '';
	var toDate = rangeParts[1] || rangeParts[0] || '';

	var postData = {
		'from_date': fromDate,
		'to_date': toDate,
		'id_branch': id_branch
	};

	$.ajax({
		url: base_url + "index.php/admin_ret_reports/physical_stock_inspect_report/ajax",
		data: postData,
		dataType: "JSON",
		type: "POST",
		success: function (data) {
			render_inspect_table(data.list || []);
			$("div.overlay").css("display", "none");
		},
		error: function () {
			$("div.overlay").css("display", "none");
			$.toaster({ priority: 'danger', title: 'Error', message: 'Failed to fetch inspect data.' });
		}
	});
}

function render_inspect_table(list) {
	if ($.fn.DataTable.isDataTable('#inspect_table')) {
		$('#inspect_table').DataTable().clear().destroy();
	}
	$('#inspect_table > tbody').empty();

	var trHTML = '';
	if (list && list.length > 0) {
		$.each(list, function (idx, row) {
			var statusBadge = '';
			var statusVal = parseInt(row.audit_status) || 0;
			var entryCount = parseInt(row.entry_count) || 0;

			if (statusVal == 1) {
				statusBadge = '<span class="badge-completed"><i class="fa fa-check"></i> Completed</span>';
			} else if (entryCount > 0) {
				statusBadge = '<span class="badge-pending"><i class="fa fa-clock-o"></i> Pending</span>';
			} else {
				statusBadge = '<span class="badge-no-entry">No Entry</span>';
			}

			// Format date for display
			var displayDate = row.audit_date || '';
			if (displayDate && displayDate.indexOf('-') > -1) {
				var parts = displayDate.split('-');
				if (parts.length == 3) {
					displayDate = parts[2] + '/' + parts[1] + '/' + parts[0];
				}
			}

			// Print button - opens the employee product report for that day
			var printBtn = entryCount > 0
				? '<button class="btn btn-xs btn-primary inspect-print-btn" data-date="' + displayDate + '"><i class="fa fa-print"></i> Print</button>'
				: '-';

			trHTML += '<tr>'
				+ '<td>' + (idx + 1) + '</td>'
				+ '<td>' + displayDate + '</td>'
				+ '<td>' + (row.employee_names || '-') + '</td>'
				+ '<td style="text-align:center;">' + entryCount + '</td>'
				+ '<td style="text-align:center;">' + statusBadge + '</td>'
				+ '<td>' + (row.completed_by_name || '-') + '</td>'
				+ '<td>' + (row.completed_on || '-') + '</td>'
				+ '<td style="text-align:center;">' + printBtn + '</td>'
				+ '</tr>';
		});
	} else {
		trHTML = '<tr><td colspan="8" class="text-center text-muted">No data found for the selected date range.</td></tr>';
	}

	$('#inspect_table > tbody').html(trHTML);

	$('#inspect_table').DataTable({
		"bSort": false,
		"bInfo": true,
		"paging": false,
		"dom": 'lBfrtip',
		"autoWidth": false,
		"buttons": [
			{
				extend: 'print',
				footer: true,
				title: 'Physical Stock Inspect Report',
				exportOptions: { columns: ':visible' }
			},
			{
				extend: 'excel',
				footer: true,
				title: 'Physical Stock Inspect Report'
			}
		]
	});
}

// Print button on inspect page - redirect to the employee product report page with the date set
$(document).on('click', '.inspect-print-btn', function () {
	var date = $(this).data('date');
	var id_branch = ($('#inspect_branch_filter').val() != '' && $('#inspect_branch_filter').val() != undefined)
		? $('#inspect_branch_filter').val()
		: ($('#inspect_branch_select').val() ? $('#inspect_branch_select').val()[0] : '');

	// Open server-side print view (standalone PHP print page)
	var url = base_url + 'index.php/admin_ret_reports/physical_stock_inspect_report/print?date=' + encodeURIComponent(date)
		+ '&id_branch=' + encodeURIComponent(id_branch)
		+ '&auto_print=1';
	window.open(url, '_blank');
});


// ==================== Mark Complete Button (Employee Product Report) ====================

// Mark Complete button handler
$(document).on('click', '#mark_audit_complete_btn', function () {
	var audit_date = $('#dt_range').val();
	var id_branch = ($('#branch_filter').val() != '' && $('#branch_filter').val() != undefined)
		? $('#branch_filter').val()
		: ($('#branch_select').val() ? $('#branch_select').val()[0] : '');

	if (!audit_date) {
		$.toaster({ priority: 'warning', title: 'Warning', message: 'Please select a date first.' });
		return;
	}
	if (!id_branch) {
		$.toaster({ priority: 'warning', title: 'Warning', message: 'Please select a branch first.' });
		return;
	}

	if (!confirm('Are you sure you want to mark this stock audit as Completed?\n\nDate: ' + audit_date + '\n\nThis action cannot be undone.')) {
		return;
	}

	$.ajax({
		url: base_url + 'index.php/admin_ret_reports/physical_stock_inspect_report/complete_audit',
		type: 'POST',
		dataType: 'JSON',
		data: {
			audit_date: audit_date,
			id_branch: id_branch
		},
		success: function (resp) {
			if (resp.status == 'success') {
				$.toaster({ priority: 'success', title: 'Success', message: resp.message });
				$('#audit_status_badge').html('<span style="background-color:#00a65a;color:#fff;padding:3px 10px;border-radius:3px;font-size:12px;"><i class="fa fa-check"></i> Completed</span>');
				$('#mark_audit_complete_btn').prop('disabled', true).removeClass('btn-warning').addClass('btn-default');
			} else {
				$.toaster({ priority: 'danger', title: 'Error', message: resp.message || 'Failed to mark complete.' });
			}
		},
		error: function () {
			$.toaster({ priority: 'danger', title: 'Error', message: 'Server error. Please try again.' });
		}
	});
});

// Check audit status after search on employee product report page
function check_audit_status_for_current_date() {
	var audit_date = $('#dt_range').val();
	var id_branch = ($('#branch_filter').val() != '' && $('#branch_filter').val() != undefined)
		? $('#branch_filter').val()
		: ($('#branch_select').val() ? $('#branch_select').val()[0] : '');

	if (!audit_date || !id_branch) {
		$('#audit_status_badge').html('');
		$('#mark_audit_complete_btn').prop('disabled', false).removeClass('btn-default').addClass('btn-warning');
		return;
	}

	$.ajax({
		url: base_url + 'index.php/admin_ret_reports/physical_stock_inspect_report/check_status',
		type: 'POST',
		dataType: 'JSON',
		data: {
			audit_date: audit_date,
			id_branch: id_branch
		},
		success: function (resp) {
			if (resp.status == 'completed') {
				$('#audit_status_badge').html('<span style="background-color:#00a65a;color:#fff;padding:3px 10px;border-radius:3px;font-size:12px;"><i class="fa fa-check"></i> Completed</span>');
				$('#mark_audit_complete_btn').prop('disabled', true).removeClass('btn-warning').addClass('btn-default');
			} else if (resp.status == 'pending') {
				$('#audit_status_badge').html('<span style="background-color:#f39c12;color:#fff;padding:3px 10px;border-radius:3px;font-size:12px;"><i class="fa fa-clock-o"></i> Pending</span>');
				$('#mark_audit_complete_btn').prop('disabled', false).removeClass('btn-default').addClass('btn-warning');
			} else {
				$('#audit_status_badge').html('');
				$('#mark_audit_complete_btn').prop('disabled', false).removeClass('btn-default').addClass('btn-warning');
			}
		}
	});
}

function get_feedbacks(from_date, to_date) {
	var company_code = $('#company_code').val();
	var company_address1 = $('#company_address1').val();
	var company_address2 = $('#company_address2').val();
	var company_city = $('#company_city').val();
	var pincode = $('#company_pincode').val();
	var company_email = $('#company_email').val();
	var company_gst_number = $('#company_gst_number').val();
	var phone = $('#phone').val();
	var branch_name = ($('#branch_name').val() != '' && $('#branch_name').val() != undefined ? $('#branch_name').val() : $("#branch_select option:selected").text());

	var title = "<div style='text-align: center;'><b><span style='font-size:12pt;'>" + company_code + "</span></b></br>"
		+ "<span style='font-size:11pt;'>" + company_address1 + "</span></br>"
		+ "<span style='font-size:11pt;'>" + company_address2 + company_city + "-" + pincode + "</span></br>"
		+ "<span style='font-size:11pt;'>GSTIN:" + company_gst_number + ", EMAIL:" + company_email + "</span></br>"
		+ "<span style='font-size:11pt;'>Contact :" + phone + "</span></br>"
		+ "<span style=font-size:12pt;>&nbsp;&nbsp;Customer Feedback Report" + "</span></div>";

	$.ajax({
		url: base_url + "index.php/admin_ret_reports/customer_feedbacks/ajax",
		type: "POST",
		dataType: "JSON",
		data: { 'from_date': from_date, 'to_date': to_date, 'branch_id': $('#fb_branch_filter').val() || '', 'staff_id': $('#fb_employee_filter').val() || '' },
		success: function (response) {
			var headers = response.headers;
			var list = response.data;

			var columns = [
				{ data: 'feedback_id', title: '#' },
				{ data: 'branch_name', title: 'Branch' },
				{ data: 'firstname', title: 'Name' },
				{ data: 'mobile', title: 'Mobile' },
				{ data: 'mail_id', title: 'Email' },
				{ data: 'date_of_birth', title: 'DOB' },
				{ data: 'date_of_anniversary', title: 'DOA' },
				{ data: 'address', title: 'Address' },
				{ data: 'pincode', title: 'Pincode' },
				{ data: 'state', title: 'State' },
				{ data: 'city', title: 'City' },
				{ data: 'source', title: 'Source' },
				{ data: 'purchase_occasion', title: 'Occasion' },
				{ data: 'staff_name', title: 'Staff' },
				{ data: 'rating_staff', title: 'Staff Rating' },
				{ data: 'rating_ambiance', title: 'Ambiance' },
				{ data: 'rating_collection', title: 'Collection' },
				{ data: 'suggestions', title: 'Suggestions' }
			];

			headers.forEach(h => {
				columns.push({
					data: 'feedback_' + h.feedback_header_id,
					title: h.short_code
				});
			});

			var oTable = $(".feedback_table").DataTable();
			oTable.clear().destroy();

			$(".feedback_table").DataTable({
				data: list,
				columns: columns,
				destroy: true,
				dom: 'Bfrtip',
				"columnDefs": [
					{
						targets: [0, 11, 12, 13],
						className: 'dt-right'
					},
				],
				order: [[0, 'desc']],
				buttons: [
					{
						extend: 'excel',
						title: "Customer Feedback Report",
						text: 'Excel',
						exportOptions: {
							columns: ':visible'
						}
					},
					{
						extend: 'print',
						title: '',
						text: 'Print',
						messageTop: title,
						exportOptions: {
							columns: ':visible'
						}
					}
				]
			});
		}
	});
}


// ==================== Feedback Report Filters ====================

$.fn.dataTable.ext.search.push(function(settings, data, dataIndex) {
	if (!$(settings.nTable).hasClass('feedback_table')) return true;

	var sourceFilter = $('#fb_source_filter').val();
	var ratingType   = $('#fb_rating_type').val();
	var ratingValue  = $('#fb_rating_value').val();

	if (sourceFilter && sourceFilter !== '') {
		var rowSource = data[11] || '';
		if (rowSource.trim() !== sourceFilter) return false;
	}

	if (ratingType && ratingType !== '' && ratingValue && ratingValue !== '') {
		var colMap = {
			'rating_ambiance':   15,
			'rating_collection': 16,
			'rating_staff':      14
		};
		var colIdx = colMap[ratingType];
		if (colIdx !== undefined) {
			var cellVal = parseInt(data[colIdx]) || 0;
			if (cellVal !== parseInt(ratingValue)) return false;
		}
	}

	return true;
});

$(document).on('change', '#fb_source_filter, #fb_rating_type, #fb_rating_value', function() {
	if ($.fn.DataTable.isDataTable('.feedback_table')) {
		$('.feedback_table').DataTable().draw();
	}
});
